import "server-only";
import { DEFAULT_BASE_URL, PramaanError } from "@pramaan/sdk";
import { fakePramaanFetch } from "./fake";
import { plainProblem } from "./plain";
import { currentMemberId } from "./session";

// The one place this app talks to Pramaan. It runs on the server only: PRAMAAN_API_KEY never
// reaches the browser. Blocks call platform routes the SDK has no method for through `pramaan()`.

type Fetch = (url: string, init: RequestInit) => Promise<Response>;

export function transport(): { baseUrl: string; apiKey: string; fetch: Fetch } {
  if (process.env.PRAMAAN_FAKE === "1")
    return { baseUrl: "http://pramaan.fake", apiKey: "fake", fetch: fakePramaanFetch };
  const apiKey = process.env.PRAMAAN_API_KEY;
  if (!apiKey)
    throw new PramaanError("connection_required", "Pramaan isn't connected yet.", {
      status: 503,
      next: "Set PRAMAAN_API_KEY on the server, then restart the app.",
    });
  return { baseUrl: process.env.PRAMAAN_BASE_URL || DEFAULT_BASE_URL, apiKey, fetch };
}

export interface PramaanRequest {
  readonly method?: "GET" | "POST" | "PUT" | "DELETE";
  readonly body?: unknown;
  readonly headers?: Record<string, string>;
}

/** Calls a Pramaan route and returns its JSON. A refusal throws PramaanError with the API's own words. */
export async function pramaan<T>(path: string, init: PramaanRequest = {}): Promise<T> {
  const t = transport();
  const res = await t.fetch(`${t.baseUrl}${path}`, {
    method: init.method ?? "GET",
    headers: {
      Authorization: `Bearer ${t.apiKey}`,
      ...(init.body !== undefined ? { "Content-Type": "application/json" } : {}),
      ...init.headers,
    },
    body: init.body === undefined ? undefined : JSON.stringify(init.body),
    cache: "no-store",
  });
  const data = await res.json().catch(() => undefined);
  if (!res.ok) {
    const e = data?.error ?? {};
    throw Object.assign(
      new PramaanError(e.code ?? "internal", e.message ?? `Pramaan answered ${res.status}.`, {
        status: res.status,
        next: e.next,
        reason: e.reason,
        requestId: e.request_id,
      }),
      // A low-balance refusal carries where to add credit; the wallet block and ErrorState use it.
      e.top_up ? { topUp: e.top_up as TopUp } : {},
    );
  }
  return data as T;
}

/** Where to add credit, from a low-balance refusal. */
export interface TopUp {
  readonly message: string;
  readonly links: readonly { readonly label: string; readonly url: string }[];
  readonly required_micro?: number;
  readonly balance_micro: number;
}

/** Runs one capability (a superpower) by id. Returns its result, or the 202 body when it waits for approval. */
export const capability = <T>(id: string, input: unknown, headers?: Record<string, string>) =>
  pramaan<T>(`/v1/capabilities/${encodeURIComponent(id)}`, { method: "POST", body: input, headers });

/**
 * The shared signed-out refusal for any block that needs a member: the screen shows "Sign in to see
 * this." and `reason` (one plain line for that block) under it.
 */
export const signedOut = (reason: string) => new PramaanError("signed_out" as never, "Sign in to see this.", { status: 401, next: reason });

/** The JSON error the browser half reads. Only plain wording goes out: no keys, headers or status codes. */
export function errorResponse(error: unknown): Response {
  if (error instanceof PramaanError) {
    const { topUp } = error as { topUp?: TopUp };
    const { message, next } = plainProblem(error.code, error.status, error.message, error.next);
    return Response.json(
      { error: { code: error.code, message, ...(next ? { next } : {}), ...(topUp ? { top_up: topUp } : {}) } },
      { status: error.status ?? 500 },
    );
  }
  console.error(error);
  return Response.json(
    { error: { code: "internal", message: "Something went wrong on the server. Try again." } },
    { status: 500 },
  );
}

export interface Viewer {
  /** The signed-in person's Pramaan member_id, when your auth maps them to one. */
  readonly memberId?: string;
  /** Whether Pramaan says they may approve calls now. The UI hides actions; the API still enforces. */
  readonly canApprove: boolean;
}

interface Member {
  readonly member_id: string;
  readonly role: "owner" | "admin" | "member" | "viewer";
  readonly may_approve: boolean;
}

/** Who is looking, resolved on the server from GET /v1/members. Unknown people are read-only. */
export async function currentViewer(request: Request): Promise<Viewer> {
  const memberId = await currentMemberId(request);
  if (!memberId) return { canApprove: false };
  const { results } = await pramaan<{ results: Member[] }>("/v1/members");
  const me = results.find((m) => m.member_id === memberId);
  return me ? { memberId, canApprove: me.may_approve } : { canApprove: false };
}

/** Headers that make a call act as the viewer (`Pramaan-Member`). */
export const asViewer = (viewer: Viewer): Record<string, string> =>
  viewer.memberId ? { "Pramaan-Member": viewer.memberId } : {};

/**
 * Who is signed in, as a Pramaan member_id (from GET /v1/members). Replace this body with your own
 * auth: look up the signed-in user and return the member_id you mapped them to. Return undefined
 * for anyone else; they get a read-only view.
 */
export async function currentMemberId(request: Request): Promise<string | undefined> {
  // Demo and tests only: with the fake on, a cookie picks the member, `none` means signed out, and
  // no cookie means the owner demo member. Never trust a cookie for this in production; it would
  // let anyone claim to be an approver.
  if (process.env.PRAMAAN_FAKE === "1") {
    const who = readCookie(request, "pramaan_member");
    return who === "none" ? undefined : (who ?? "mbr_owner");
  }
  return undefined;
}

/**
 * Your own reference for the signed-in person, as the connections block sends it to Pramaan
 * (`endUserRef`: 1 to 128 letters, digits, `_`, `.` or `-`; never an email or name). Replace this
 * body with your user id. Return undefined when nobody is signed in.
 */
export async function currentEndUserRef(request: Request): Promise<string | undefined> {
  // Demo and tests only, like the member cookie above.
  if (process.env.PRAMAAN_FAKE === "1") {
    if (readCookie(request, "pramaan_member") === "none") return undefined;
    return readCookie(request, "pramaan_user") ?? "user-42";
  }
  return undefined;
}

function readCookie(request: Request, name: string): string | undefined {
  for (const part of (request.headers.get("cookie") ?? "").split(";")) {
    const [key, ...value] = part.trim().split("=");
    if (key === name) return decodeURIComponent(value.join("=")) || undefined;
  }
  return undefined;
}

/** Authorise writes using trusted membership data. Wire this alongside currentMemberId. */
export async function canWrite(member: string, scope: string): Promise<boolean> {
  if (process.env.PRAMAAN_FAKE === "1") return member === "mbr_owner" && scope === member;
  // Deny until the host app checks this member's write role in the chosen workspace.
  return false;
}

// An in-memory Pramaan for demos and tests (PRAMAAN_FAKE=1). It answers the platform routes the
// blocks use with the documented shapes and the API's own messages. Nothing leaves the process.
//
// Routes beyond approvals live beside it: fake-platform.ts (missions, jobs, wallet, connections)
// and fake-assessment.ts (exams, invitations, email). They share this state.
//
// One deliberate difference: the real API lets only a member signed in to the dashboard list or
// decide approvals, so a server key gets 403 today. The fake accepts the key and
// treats `Pramaan-Member` as the person deciding, which is the access the real API does not give yet.

import { assessmentRoutes, type AssessmentState } from "./fake-assessment";
import { type ActivityState, activityRoutes } from "./fake-activity";
import { type ConsentState, consentRoutes } from "./fake-consent";
import { catalogueDescribe, catalogueRoutes } from "./fake-catalogue";
import { addFakeMemory as addMemoryTo, memoryRoutes, type MemoryState } from "./fake-memory";
import { completeConnection, platformRoutes, type PlatformState } from "./fake-platform";
import { type Wave3State, wave3Routes } from "./fake-wave3";

type ApprovalStatus = "pending" | "approved" | "denied" | "cancelled";

export interface FakeApproval {
  id: string;
  capability: string;
  priceMicro: number;
  input: unknown;
  requestedBy: { kind: string; act?: string; member_id?: string };
  createdAt: number;
  expiresAt: number;
  status: ApprovalStatus;
  decidedBy?: string;
  decidedAt?: number;
  /** How many times the approved call ran. Must never pass 1. */
  runs: number;
}

export interface FakeMember {
  member_id: string;
  email: string;
  role: "owner" | "admin" | "member" | "viewer";
  can_approve: boolean;
  may_approve: boolean;
}

export interface FakeRequest {
  method: string;
  path: string;
  headers: Record<string, string>;
  body?: unknown;
}

export interface FakeState {
  approvals: Map<string, FakeApproval>;
  members: FakeMember[];
  capabilities: Record<string, { description: string; effect_class: string }>;
  failures: { method: string; path: string; status: number; error: Record<string, unknown> }[];
  requests: FakeRequest[];
  seq: number;
  now: () => number;
  /** How long a fake mission step takes, ms (PRAMAAN_FAKE_STEP_MS). */
  stepMs: number;
  /** Credit set aside, by what holds it: running missions, unused invitations. */
  holds: Map<string, number>;
  platform?: PlatformState;
  assessment?: AssessmentState;
  memory?: MemoryState;
  consent?: ConsentState;
  activity?: ActivityState;
  wave3?: Wave3State;
}

/** What a route handler in a fake-*.ts file gets to work with. */
export interface FakeCtx {
  s: FakeState;
  method: string;
  path: string;
  url: URL;
  headers: Record<string, string>;
  body: unknown;
  now: number;
  json: (status: number, body: unknown) => Response;
  fail: (status: number, code: string, message: string) => Response;
  addApproval: (a: Partial<FakeApproval> & Pick<FakeApproval, "capability" | "input">) => string;
}

const MINUTE = 60_000;
const TTL = 24 * 60 * MINUTE;

function seed(): FakeState {
  const now = Date.now();
  const s: FakeState = {
    approvals: new Map(),
    members: [
      { member_id: "mbr_owner", email: "owner@example.com", role: "owner", can_approve: true, may_approve: true },
      { member_id: "mbr_viewer", email: "viewer@example.com", role: "viewer", can_approve: false, may_approve: false },
    ],
    capabilities: {
      "email.send": { description: "Sends one email from your connected inbox.", effect_class: "external_irreversible" },
      "sms.send": { description: "Sends a text message to one phone number.", effect_class: "external_irreversible" },
      "social.post.publish": { description: "Publishes or schedules a post on your connected social accounts.", effect_class: "external_irreversible" },
    },
    failures: [],
    requests: [],
    seq: 0,
    now: () => Date.now(),
    stepMs: Number(process.env.PRAMAAN_FAKE_STEP_MS) || 2_000,
    holds: new Map(),
  };
  addTo(s, {
    capability: "email.send",
    priceMicro: 2_000,
    input: { to: "pat@example.com", subject: "Your invoice", text: "Hi Pat, your invoice is attached." },
    requestedBy: { kind: "key", member_id: "mbr_viewer" },
    createdAt: now - 5 * MINUTE,
  });
  addTo(s, {
    capability: "sms.send",
    priceMicro: 9_100,
    input: { to: "+15555550100", text: "Your table is ready." },
    requestedBy: { kind: "partner", act: "app" },
    createdAt: now - 30 * MINUTE,
  });
  return s;
}

function addTo(s: FakeState, a: Partial<FakeApproval> & Pick<FakeApproval, "capability" | "input">): string {
  const id = a.id ?? `apr_fake${String(++s.seq).padStart(4, "0")}`;
  const createdAt = a.createdAt ?? s.now();
  s.approvals.set(id, {
    priceMicro: 1_000,
    requestedBy: { kind: "key" },
    expiresAt: createdAt + TTL,
    status: "pending",
    runs: 0,
    ...a,
    id,
    createdAt,
  });
  return id;
}

const g = globalThis as { __pramaanFake?: FakeState };

/** The fake's state, shared across route modules in one process. */
export function fakeState(): FakeState {
  return (g.__pramaanFake ??= seed());
}

/** Back to the seed data. */
export function resetFake(): FakeState {
  g.__pramaanFake = seed();
  return g.__pramaanFake;
}

/** Adds a call waiting for approval (as a send held by the API would). Returns its id. */
export function addFakeApproval(a: Partial<FakeApproval> & Pick<FakeApproval, "capability" | "input">): string {
  return addTo(fakeState(), a);
}

/** The next matching request fails with this error body, as the API would send it. */
export function failNext(method: string, path: string, status: number, error: Record<string, unknown>): void {
  fakeState().failures.push({ method, path, status, error });
}

/** The end user finishes signing in to an app (what the hosted sign-in page does). */
export function completeFakeConnection(user: string, app: string): void {
  completeConnection(fakeState(), user, app);
}

/** Adds a private memory for a person, as a chat would over time. */
export function addFakeMemory(s: FakeState, user: string, text: string): string {
  return addMemoryTo(s, user, text);
}

/** Another member decides it first. */
export function decideElsewhere(id: string, status: "approved" | "denied", by = "mbr_other"): void {
  const a = fakeState().approvals.get(id);
  if (!a) return;
  Object.assign(a, { status, decidedBy: by, decidedAt: fakeState().now() });
  if (status === "approved") a.runs++;
}

const json = (status: number, body: unknown) => Response.json(body, { status });
const fail = (status: number, code: string, message: string) => json(status, { error: { code, message } });
const iso = (ms: number) => new Date(ms).toISOString();

function summary(a: FakeApproval) {
  return {
    approval_id: a.id,
    capability: a.capability,
    price_micro: a.priceMicro,
    input: a.input,
    requested_by: a.requestedBy,
    created_at: iso(a.createdAt),
    expires_at: iso(a.expiresAt),
  };
}

// Mirrors the API's approval job view (apps/api/src/approvals.ts approvalJob).
function job(a: FakeApproval, now: number) {
  const expired = a.status === "pending" && a.expiresAt <= now;
  const base = {
    job_id: a.id,
    approval_id: a.id,
    capability: a.capability,
    approval: { status: expired ? "expired" : a.status, ...(a.decidedBy ? { decided_by: a.decidedBy } : {}) },
    created_at: iso(a.createdAt),
    updated_at: iso(a.decidedAt ?? a.createdAt),
  };
  const failed = (message: string) => ({ ...base, status: "failed", error: { code: "forbidden", message, effect: "none" } });
  if (expired) return failed("No member approved this call in time, so nothing ran. Send it with a new key.");
  if (a.status === "denied") return failed("A member declined this call, so nothing ran and nothing was charged.");
  if (a.status === "cancelled") return { ...base, status: "cancelled" };
  if (a.status === "approved") return { ...base, status: "done", result: { status: "sent" } };
  return { ...base, status: "running" };
}

/** A drop-in `fetch` that answers like the Pramaan API. */
export async function fakePramaanFetch(url: string, init: RequestInit = {}): Promise<Response> {
  const s = fakeState();
  const method = (init.method ?? "GET").toUpperCase();
  const u = new URL(url);
  const path = u.pathname;
  const headers = Object.fromEntries(new Headers(init.headers).entries());
  const body = typeof init.body === "string" ? JSON.parse(init.body) : undefined;
  s.requests.push({ method, path, headers, body });

  const f = s.failures.findIndex((x) => x.method === method && x.path === path);
  if (f >= 0) {
    const [failure] = s.failures.splice(f, 1);
    return json(failure.status, { error: failure.error });
  }
  if (headers.authorization !== "Bearer fake") return fail(401, "unauthorized", "Send your API key as a Bearer token.");

  const now = s.now();
  if (method === "GET" && path === "/v1/members") return json(200, { results: s.members });

  let m = path.match(/^\/v1\/capabilities\/([^/]+)$/);
  if (method === "GET" && m) {
    const extra = catalogueDescribe(decodeURIComponent(m[1]));
    const c = s.capabilities[decodeURIComponent(m[1])] ?? extra;
    if (!c) return fail(404, "not_found", "No capability with that id. List them with GET /v1/capabilities.");
    return json(200, { id: decodeURIComponent(m[1]), mode: "sync", available: true, needs_connection: true, request_schema: {}, result_schema: {}, ...c, ...extra });
  }

  if (method === "GET" && path === "/v1/approvals") {
    const pending = [...s.approvals.values()].filter((a) => a.status === "pending" && a.expiresAt > now);
    return json(200, { results: pending.sort((a, b) => b.createdAt - a.createdAt).map(summary) });
  }

  m = path.match(/^\/v1\/approvals\/([^/]+)(\/decide)?$/);
  if (m) {
    const a = s.approvals.get(decodeURIComponent(m[1]));
    if (method === "GET" && !m[2]) {
      if (!a) return fail(404, "not_found", "Approval not found. Check the approval_id.");
      return json(200, { ...summary(a), job: job(a, now) });
    }
    if (method === "POST" && m[2]) {
      const member = s.members.find((x) => x.member_id === headers["pramaan-member"]);
      if (!member)
        return fail(403, "forbidden", "Only a member signed in to this workspace can see or decide approvals; keys and apps cannot.");
      if (!member.may_approve) return fail(403, "forbidden", "This member may not approve calls. Ask an approver.");
      const decision = (body as { decision?: unknown } | undefined)?.decision;
      if (decision !== "approve" && decision !== "deny")
        return fail(400, "invalid_request", 'Send {"decision": "approve"} or {"decision": "deny"}.');
      if (!a) return fail(404, "not_found", "Approval not found. Check the approval_id.");
      if (a.status !== "pending" || a.expiresAt <= now)
        return fail(409, "conflict", "This approval was already decided, or it has expired.");
      const status = decision === "approve" ? "approved" : "denied";
      Object.assign(a, { status, decidedBy: member.member_id, decidedAt: now });
      if (status === "approved") a.runs++;
      return json(200, { approval_id: a.id, status: a.status, job: job(a, now) });
    }
  }
  const ctx: FakeCtx = { s, method, path, url: u, headers, body, now, json, fail, addApproval: (a) => addTo(s, a) };
  return platformRoutes(ctx) ?? assessmentRoutes(ctx) ?? memoryRoutes(ctx) ?? consentRoutes(ctx) ?? activityRoutes(ctx) ?? wave3Routes(ctx) ?? catalogueRoutes(ctx) ?? fail(404, "not_found", "No such route.");
}

import type { FakeCtx, FakeState } from "./fake";

// Fake outcomes ("missions"), jobs, wallet, usage, accounts and app connections: the platform routes
// the mission runner, wallet and connections blocks use, with the documented shapes. Extends the
// core fake (fake.ts); it keeps its own state under `s.platform`.
//
// Not in the OpenAPI yet: `progress` on a running outcome job (step statuses and the
// charge so far), and the exact answer of a step that waits for a member's approval.

const DAY = 86_400_000;

export interface FakeStep {
  id: string;
  label: string;
  capability: string;
  effect_class: string;
  required: true;
  max_calls: 1;
  requires_approval: boolean;
  price_max_micro: number;
  mode: "sync";
  needs_connection: false;
}

interface Mission {
  id: string;
  description: string;
  effect_class: string;
  input_schema: Record<string, unknown>;
  check(input: Record<string, unknown>): string | undefined;
  steps: FakeStep[];
  result(input: Record<string, unknown>): unknown;
}

const step = (id: string, label: string, capability: string, price: number, approval = false, effect = "read_only"): FakeStep => ({
  id,
  label,
  capability,
  effect_class: effect,
  required: true,
  max_calls: 1,
  requires_approval: approval,
  price_max_micro: price,
  mode: "sync",
  needs_connection: false,
});

const MISSIONS: Mission[] = [
  {
    id: "company.research",
    description: "One sourced profile of a company from its domain or name: register record, news, site pages, social page, and a written summary.",
    effect_class: "read_only",
    input_schema: {
      type: "object",
      properties: {
        domain: { type: "string", maxLength: 2048, description: "Company website domain, e.g. example.com. Send this or name." },
        name: { type: "string", minLength: 1, maxLength: 200, description: "Company name. Send this or domain." },
      },
    },
    check: (i) => (i.domain || i.name ? undefined : "Send a domain or a name for the company."),
    steps: [
      step("register", "Look up the company register", "companies.registry.search", 20_000),
      step("news", "Collect recent news", "companies.news", 50_000),
      step("site", "Read the company's site", "web.read", 40_000),
      step("summary", "Write the summary", "llm.complete", 100_000),
    ],
    result: (i) => ({ company: i.name ?? i.domain, summary: `A sourced profile of ${String(i.name ?? i.domain)}.`, sources: 4 }),
  },
  {
    id: "broadcast.send",
    description: "Draft a broadcast to subscribed contacts, show the recipient count, the opted-out removed and the message, and send it after approval.",
    effect_class: "external_irreversible",
    input_schema: {
      type: "object",
      required: ["accountId", "name", "text"],
      properties: {
        accountId: { type: "string", minLength: 1, maxLength: 128, description: "The connected messaging account to send from." },
        name: { type: "string", minLength: 1, maxLength: 256, description: "A name for the broadcast, for your own reference." },
        text: { type: "string", minLength: 1, maxLength: 4096, description: "The message, exactly as it will be sent to every recipient." },
        tag: { type: "string", minLength: 1, maxLength: 128, description: "Only contacts with this tag." },
      },
    },
    check: (i) => (i.accountId && i.name && i.text ? undefined : "Send accountId, name and text."),
    steps: [
      step("contacts", "List the subscribed contacts", "outreach.contacts.list", 5_000),
      step("draft", "Create the broadcast", "outreach.broadcast.create", 5_000),
      step("send", "Send it", "outreach.broadcast.send", 90_000, true, "external_irreversible"),
    ],
    result: (i) => ({ broadcast: i.name, recipients: 42, optedOutRemoved: 3 }),
  },
];

const priceOf = (m: Mission) => m.steps.reduce((n, x) => n + x.price_max_micro, 0);
const requiresApproval = (m: Mission) => m.steps.some((x) => x.requires_approval);

function planOf(m: Mission, input: unknown): string {
  let h = 5381;
  for (const ch of `${m.id}:${JSON.stringify(input)}`) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0;
  return `plan_${h.toString(16)}`;
}

interface Job {
  id: string;
  mission: Mission;
  input: Record<string, unknown>;
  plan: string;
  holdMicro: number;
  createdAt: number;
  updatedAt: number;
  status: "running" | "done" | "failed" | "cancelled";
  idx: number;
  /** When the step before this one ended (or the run started). */
  cursorAt: number;
  stepStart?: number;
  done: string[];
  charged: number;
  approvals: Record<string, string>;
  error?: { code: string; message: string };
  waiting?: string;
  settled: boolean;
}

interface Conn {
  connectionId: string;
  app: string;
  status: "active" | "pending" | "failed" | "expired" | "disabled" | "revoked";
  name?: string;
  connectedAt: string;
  access: "read" | "read-write" | "full" | "limited";
  deleteApproval?: string;
}

interface UsageRow {
  day: string;
  capability: string;
  calls: number;
  spend_micro: number;
}

export interface PlatformState {
  jobs: Map<string, Job>;
  idem: Map<string, string>;
  balanceMicro: number;
  usage: UsageRow[];
  connections: Map<string, Conn[]>;
  seq: number;
}

const dayOf = (ms: number) => new Date(ms).toISOString().slice(0, 10);

function seedPlatform(s: FakeState): PlatformState {
  const now = s.now();
  const usage: UsageRow[] = [];
  const caps: [string, number][] = [["email.send", 2_000], ["llm.complete", 12_000], ["web.read", 4_000], ["companies.news", 50_000]];
  for (let d = 0; d < 14; d++)
    caps.forEach(([capability, price], k) => {
      const calls = 3 + ((d * 7 + k * 5) % 9);
      usage.push({ day: dayOf(now - d * DAY), capability, calls, spend_micro: calls * price });
    });
  const at = (ago: number) => new Date(now - ago * DAY).toISOString();
  const connections = new Map<string, Conn[]>([
    [
      "user-42",
      [
        { connectionId: "apn_gmail1", app: "gmail", status: "active", name: "pat@example.com", connectedAt: at(30), access: "read-write" },
        { connectionId: "apn_cal1", app: "googlecalendar", status: "expired", name: "pat@example.com", connectedAt: at(90), access: "read" },
        { connectionId: "apn_gh1", app: "github", status: "revoked", connectedAt: at(200), access: "full" },
      ],
    ],
  ]);
  return { jobs: new Map(), idem: new Map(), balanceMicro: 12_340_000, usage, connections, seq: 0 };
}

export const platform = (s: FakeState): PlatformState => (s.platform ??= seedPlatform(s));

const held = (s: FakeState) => [...s.holds.values()].reduce((n, x) => n + x, 0);

function topUp(c: FakeCtx, required: number) {
  const available = platform(c.s).balanceMicro - held(c.s);
  return {
    message: `This needs up to $${(required / 1e6).toFixed(2)} and your balance is $${(available / 1e6).toFixed(2)}. Add credit, then try again.`,
    links: [{ label: "Add credit", url: "https://app.pramaan.dev/settings/wallet" }],
    required_micro: required,
    balance_micro: available,
  };
}

function addUsage(p: PlatformState, day: string, capability: string, spend: number) {
  const row = p.usage.find((r) => r.day === day && r.capability === capability);
  if (row) {
    row.calls++;
    row.spend_micro += spend;
  } else p.usage.push({ day, capability, calls: 1, spend_micro: spend });
}

/** Charges what a finished job did and releases its hold. Runs once. */
function settle(c: FakeCtx, j: Job) {
  if (j.settled) return;
  j.settled = true;
  c.s.holds.delete(`job:${j.id}`);
  const p = platform(c.s);
  p.balanceMicro -= j.charged;
  for (const id of j.done) {
    const st = j.mission.steps.find((x) => x.id === id)!;
    addUsage(p, dayOf(j.updatedAt), st.capability, st.price_max_micro);
  }
}

function fail(c: FakeCtx, j: Job, code: string, message: string) {
  j.status = "failed";
  j.error = { code, message };
  j.updatedAt = c.now;
  settle(c, j);
}

/** Moves a running job forward to `now`: each step takes `stepMs`; an approval step waits for a member. */
function advance(c: FakeCtx, j: Job) {
  while (j.status === "running") {
    const st = j.mission.steps[j.idx];
    if (!st) {
      j.status = "done";
      j.updatedAt = j.cursorAt;
      settle(c, j);
      return;
    }
    if (st.requires_approval && j.stepStart === undefined) {
      const id = (j.approvals[st.id] ??= c.addApproval({
        capability: st.capability,
        priceMicro: st.price_max_micro,
        input: j.input,
        requestedBy: { kind: "key" },
        createdAt: c.now,
      }));
      const a = c.s.approvals.get(id)!;
      if (a.status === "pending") {
        j.waiting = st.id;
        return;
      }
      j.waiting = undefined;
      if (a.status !== "approved") return fail(c, j, "forbidden", "A member declined this step, so it did not run and nothing more was charged.");
      j.stepStart = a.decidedAt ?? c.now;
    }
    j.stepStart ??= j.cursorAt;
    if (c.now < j.stepStart + c.s.stepMs) return;
    j.done.push(st.id);
    j.charged += st.price_max_micro;
    j.cursorAt = j.stepStart + c.s.stepMs;
    j.stepStart = undefined;
    j.idx++;
  }
}

function report(j: Job) {
  const done = j.mission.steps.filter((x) => j.done.includes(x.id));
  return {
    outcome: j.mission.id,
    version: 1,
    plan: j.plan,
    status: j.status === "done" ? "done" : "failed",
    ...(j.status === "done" ? { result: j.mission.result(j.input) } : {}),
    evidence: [],
    missing: [],
    steps: done.map((x) => ({ id: x.id, status: "ok", calls: 1, capability: x.capability, effect_class: x.effect_class, effect: x.effect_class === "read_only" ? "none" : "done" })),
    cost: {
      hold_micro: j.holdMicro,
      charged_micro: j.charged,
      capabilities: done.map((x) => ({ id: x.capability, calls: 1, charged_micro: x.price_max_micro })),
    },
  };
}

function jobView(c: FakeCtx, j: Job) {
  advance(c, j);
  const running = j.status === "running";
  const steps = j.mission.steps.map((x, i) => {
    let status: string;
    if (j.done.includes(x.id)) status = "done";
    else if (j.status === "failed" && i === j.idx) status = "failed";
    else if (j.status === "cancelled" || j.status === "failed") status = "skipped";
    else if (i === j.idx) status = j.waiting === x.id ? "waiting_approval" : "running";
    else status = "waiting";
    return { id: x.id, label: x.label, status, ...(j.approvals[x.id] ? { approval_id: j.approvals[x.id] } : {}) };
  });
  return {
    job_id: j.id,
    capability: j.mission.id,
    status: j.status,
    ...(running ? {} : { result: report(j) }),
    ...(j.error ? { error: { ...j.error, effect: "none" } } : {}),
    progress: { steps, charged_micro: j.charged },
    created_at: new Date(j.createdAt).toISOString(),
    updated_at: new Date(j.updatedAt).toISOString(),
  };
}

const info = (m: Mission) => ({
  id: m.id,
  description: m.description,
  version: 1,
  effect_class: m.effect_class,
  mode: "async",
  price_max_micro: priceOf(m),
  personal_data: false,
  available: true,
  ...(requiresApproval(m) ? { requires_approval: true } : {}),
  capability_ids: m.steps.map((x) => x.capability),
});

function connView(c: Conn) {
  return { connectionId: c.connectionId, app: c.app, status: c.status, ...(c.name ? { name: c.name } : {}), connectedAt: c.connectedAt };
}

function userConns(c: FakeCtx, user: string): Conn[] {
  const p = platform(c.s);
  const list = p.connections.get(user) ?? [];
  p.connections.set(user, list);
  // A delete waits for a member's approval; apply it once it is approved.
  for (const conn of [...list]) {
    const a = conn.deleteApproval ? c.s.approvals.get(conn.deleteApproval) : undefined;
    if (a?.status === "approved") list.splice(list.indexOf(conn), 1);
    else if (a && a.status !== "pending") conn.deleteApproval = undefined;
  }
  return list;
}

/** The end user signs in to the app (what the hosted sign-in page does). */
export function completeConnection(s: FakeState, user: string, app: string) {
  const list = platform(s).connections.get(user) ?? [];
  const conn = list.find((x) => x.app === app && x.status === "pending");
  if (conn) Object.assign(conn, { status: "active", name: "pat@example.com", connectedAt: new Date(s.now()).toISOString() });
}

function capabilityRoute(c: FakeCtx, id: string): Response | undefined {
  const p = platform(c.s);
  const b = (c.body ?? {}) as Record<string, unknown>;
  if (id.startsWith("apps.connection")) {
    const user = b.endUserRef;
    if (typeof user !== "string" || !/^[A-Za-z0-9_.-]{1,128}$/.test(user))
      return c.fail(400, "invalid_request", "endUserRef is required: your own reference for the end user, 1 to 128 letters, digits, '_', '.' or '-'.");
    const list = userConns(c, user);
    const app = typeof b.app === "string" ? b.app : undefined;
    if (id === "apps.connections.list") {
      return c.json(200, { results: list.filter((x) => !app || x.app === app).map((x) => ({ app: x.app, status: x.status, connectedAt: x.connectedAt, access: x.access })) });
    }
    if (id === "apps.connections.list-detailed") {
      return c.json(200, { results: list.filter((x) => (!app || x.app === app) && x.status !== "revoked" && x.status !== "pending").map(connView) });
    }
    if (id === "apps.connection.start") {
      if (typeof app !== "string" || !/^[a-z0-9_-]{1,64}$/.test(app)) return c.fail(400, "invalid_request", "app is required: the app id, lowercase, like \"gmail\".");
      const existing = list.find((x) => x.app === app);
      if (existing) existing.status = "pending";
      else list.push({ connectionId: `apn_${app}${++p.seq}`, app, status: "pending", connectedAt: new Date(c.now).toISOString(), access: "read-write" });
      const redirect = typeof b.redirectUrl === "string" ? b.redirectUrl : "http://localhost:3100/";
      const connect = new URL("/api/demo/connect", redirect);
      connect.search = new URLSearchParams({ user, app, redirect }).toString();
      return c.json(200, { connectUrl: connect.toString(), expiresAt: new Date(c.now + 600_000).toISOString() });
    }
    if (id === "apps.connection.get") {
      const conn = list.find((x) => x.connectionId === b.connectionId);
      if (!conn) return c.fail(404, "not_found", "No such connection. List them with apps.connections.list-detailed.");
      return c.json(200, { ...connView(conn), updatedAt: conn.connectedAt });
    }
    if (id === "apps.connection.revoke") {
      const live = list.filter((x) => x.app === app && x.status !== "revoked");
      live.forEach((x) => (x.status = "revoked"));
      return c.json(200, { revoked: live.length });
    }
    if (id === "apps.connection.delete") {
      const conn = list.find((x) => x.connectionId === b.connectionId);
      if (!conn) return c.fail(404, "not_found", "No such connection. List them with apps.connections.list-detailed.");
      if (b.confirm !== true) return c.fail(400, "invalid_request", "Send confirm: true to delete this connection for good.");
      conn.deleteApproval ??= c.addApproval({ capability: id, priceMicro: 0, input: b, requestedBy: { kind: "key" }, createdAt: c.now });
      return c.json(202, { job_id: conn.deleteApproval, status: "running", held_micro: 0 });
    }
  }
  if (id === "billing.credits.balance") {
    if (b.customerId !== "cus_example") return c.fail(404, "not_found", "No customer with that id. List them with billing.customers.list.");
    return c.json(200, { balances: [{ kind: "money", available: { amount: 1999, currency: "USD" }, reserved: { amount: 0, currency: "USD" } }] });
  }
  return undefined;
}

/** The platform routes of this fake. Returns undefined for a route it doesn't serve. */
export function platformRoutes(c: FakeCtx): Response | undefined {
  const { method, path } = c;
  const p = platform(c.s);

  if (method === "GET" && path === "/v1/balance") {
    const h = held(c.s);
    const today = p.usage.filter((r) => r.day === dayOf(c.now)).reduce((n, r) => n + r.spend_micro, 0);
    return c.json(200, { balance_micro: p.balanceMicro - h, today_spend_micro: today, daily_cap_micro: null, daily_cap_message: "no daily cap", held_micro: h });
  }
  if (method === "GET" && path === "/v1/usage") {
    const to = c.url.searchParams.get("to") ?? dayOf(c.now);
    const from = c.url.searchParams.get("from") ?? dayOf(Date.parse(to) - 29 * DAY);
    const results = p.usage.filter((r) => r.day >= from && r.day <= to).sort((a, b) => (a.day === b.day ? a.capability.localeCompare(b.capability) : a.day.localeCompare(b.day)));
    return c.json(200, { from, to, results });
  }
  if (method === "GET" && path === "/v1/accounts") {
    const at = new Date(c.now - 40 * DAY).toISOString();
    return c.json(200, {
      results: [
        { id: "acc_mail1", label: "Support inbox", family: "mail", origin: "own", status: "connected", created_at: at },
        { id: "acc_sms1", label: "Sender line", family: "messaging", origin: "platform", status: "connected", created_at: at },
        { id: "acc_cal1", label: "Team calendar", family: "calendar", origin: "own", status: "disconnected", created_at: at },
      ],
    });
  }

  if (method === "GET" && path === "/v1/outcomes") return c.json(200, { results: MISSIONS.map(info) });
  let m = path.match(/^\/v1\/outcomes\/([^/]+?)(\/estimate)?$/);
  if (m) {
    const mission = MISSIONS.find((x) => x.id === decodeURIComponent(m![1]));
    if (!mission) return c.fail(404, "not_found", "No outcome with that id. List them with GET /v1/outcomes.");
    if (method === "GET" && !m[2])
      return c.json(200, { ...info(mission), input_schema: mission.input_schema, options_schema: { type: "object", properties: {} }, result_schema: { type: "object" }, steps: mission.steps });
    const input = ((c.body as { input?: Record<string, unknown> } | undefined)?.input ?? {}) as Record<string, unknown>;
    if (method === "POST" && m[2]) {
      const problem = mission.check(input);
      const price = priceOf(mission);
      const available = p.balanceMicro - held(c.s);
      return c.json(200, {
        outcome: mission.id,
        version: 1,
        plan: planOf(mission, input),
        ready: !problem,
        can_run: !problem && available >= price,
        price_max_micro: price,
        steps: mission.steps.map((x) => ({ id: x.id, label: x.label, capability: x.capability, requires_approval: x.requires_approval, price_max_micro: x.price_max_micro })),
        ...(problem ? { message: problem } : {}),
        ...(available < price ? { top_up: topUp(c, price) } : {}),
      });
    }
    if (method === "POST" && !m[2]) {
      const problem = mission.check(input);
      if (problem) return c.json(400, { error: { code: "invalid_request", message: problem, effect: "none" } });
      const plan = planOf(mission, input);
      if (requiresApproval(mission) && c.headers["pramaan-plan"] !== plan)
        return c.json(403, { error: { code: "forbidden", reason: "approval_required", message: "This outcome needs approval. Estimate it, show a person the plan, then send its plan in Pramaan-Plan.", effect: "none" } });
      const key = c.headers["idempotency-key"];
      const prior = key ? p.idem.get(`${mission.id}:${key}`) : undefined;
      if (prior) return c.json(202, { job_id: prior, status: "running", held_micro: p.jobs.get(prior)?.holdMicro ?? 0 });
      const price = priceOf(mission);
      if (p.balanceMicro - held(c.s) < price)
        return c.json(402, { error: { code: "spend_cap_reached", reason: "balance", message: "Your balance is too low for this run. Add credit, then try again.", effect: "none", required_micro: price, top_up: topUp(c, price) } });
      const id = `job_fake${String(++p.seq).padStart(4, "0")}`;
      p.jobs.set(id, { id, mission, input, plan, holdMicro: price, createdAt: c.now, updatedAt: c.now, status: "running", idx: 0, cursorAt: c.now, done: [], charged: 0, approvals: {}, settled: false });
      c.s.holds.set(`job:${id}`, price);
      if (key) p.idem.set(`${mission.id}:${key}`, id);
      return c.json(202, { job_id: id, status: "running", held_micro: price });
    }
  }

  m = path.match(/^\/v1\/jobs\/([^/]+?)(\/cancel)?$/);
  if (m) {
    const j = p.jobs.get(decodeURIComponent(m[1]));
    if (!j) return undefined; // another block's job (approvals answer under their own routes)
    if (method === "GET" && !m[2]) return c.json(200, jobView(c, j));
    if (method === "POST" && m[2]) {
      advance(c, j);
      if (j.status !== "running") return c.fail(409, "conflict", "This job already finished, so there is nothing to cancel.");
      j.status = "cancelled";
      j.updatedAt = c.now;
      settle(c, j);
      return c.json(200, jobView(c, j));
    }
  }

  m = path.match(/^\/v1\/capabilities\/([^/]+)$/);
  if (method === "POST" && m) return capabilityRoute(c, decodeURIComponent(m[1]));
  return undefined;
}

export const fakeMissionIds = MISSIONS.map((x) => x.id);

import type { FakeCtx, FakeState } from "./fake";
import { platform } from "./fake-platform";

// Fake exams, invitations, results and integrity reports (assessment.* superpowers) plus the
// email.send that delivers an invitation, with the documented shapes. Extends the core fake.
//
// Publish runs at once. Revoke and email.send wait for a member's approval in the approvals
// inbox, as a call made with a key does; they take effect once it is approved. Revoking an
// invitation releases the credit held for it.

const DAY = 86_400_000;
const HOLD_MICRO = 500_000;

type ExamStatus = "draft" | "active" | "archived";
type InviteStatus = "pending" | "opened" | "started" | "completed" | "expired" | "revoked";

interface Question {
  text: string;
  points?: number;
  required?: boolean;
  type: string;
  content: unknown;
  order: number;
}

interface Exam {
  ref: string;
  title: string;
  description?: string;
  durationMinutes: number;
  passScore?: number;
  proctoring: { enabled: boolean; profile?: string };
  identityRequired: boolean;
  status: ExamStatus;
  questions: Question[];
}

interface Invite {
  ref: string;
  examRef: string;
  email: string;
  status: InviteStatus;
  createdAt: number;
  expiresAt: number;
  emailedAt?: number;
  revokedAt?: number;
  link: string;
  revokeApproval?: string;
  /** The result and integrity report exist only once grading has finished. */
  ready: boolean;
  score?: number;
  flagged?: boolean;
}

interface Email {
  approval: string;
  to: string[];
  text: string;
  applied: boolean;
}

export interface AssessmentState {
  exams: Map<string, Exam>;
  invites: Map<string, Invite>;
  idem: Map<string, string>;
  emails: Email[];
  /** Emails that went out, after approval. */
  sent: { to: string[]; text: string }[];
  seq: number;
}

const iso = (ms: number) => new Date(ms).toISOString();

function seedAssessment(s: FakeState): AssessmentState {
  const now = s.now();
  const st: AssessmentState = { exams: new Map(), invites: new Map(), idem: new Map(), emails: [], sent: [], seq: 0 };
  const q = (text: string, type = "mcq", order = 0): Question => ({
    text,
    type,
    points: 5,
    required: true,
    order,
    content:
      type === "mcq"
        ? { options: [{ text: "Yes", isCorrect: true }, { text: "No", isCorrect: false }], allowMultiple: false }
        : { maxWords: 200, rubric: "Clear, correct, short." },
  });
  st.exams.set("exm_active1", {
    ref: "exm_active1",
    title: "Backend engineer screen",
    description: "Forty minutes: HTTP, SQL and one design question.",
    durationMinutes: 40,
    passScore: 70,
    proctoring: { enabled: true, profile: "record" },
    identityRequired: true,
    status: "active",
    questions: [q("Is a PUT request idempotent?", "mcq", 1), q("Does an index always speed up a query?", "mcq", 2), q("Explain how you would page a large result set.", "text", 3)],
  });
  st.exams.set("exm_draft1", {
    ref: "exm_draft1",
    title: "Customer support quiz",
    durationMinutes: 20,
    proctoring: { enabled: false },
    identityRequired: false,
    status: "draft",
    questions: [q("Should you apologise before you know the cause?", "mcq", 1)],
  });
  const invite = (ref: string, email: string, status: InviteStatus, extra: Partial<Invite> = {}) =>
    st.invites.set(ref, { ref, examRef: "exm_active1", email, status, createdAt: now - 3 * DAY, expiresAt: now + 7 * DAY, link: `https://tests.example.com/i/${ref}`, ready: false, ...extra });
  invite("inv_ada", "ada@example.com", "pending", { emailedAt: now - 3 * DAY });
  invite("inv_grace", "grace@example.com", "started", { emailedAt: now - 2 * DAY });
  invite("inv_alan", "alan@example.com", "completed", { emailedAt: now - 2 * DAY, ready: true, score: 82 });
  invite("inv_linus", "linus@example.com", "expired", { createdAt: now - 20 * DAY, expiresAt: now - 10 * DAY, emailedAt: now - 20 * DAY });
  for (const i of st.invites.values()) if (i.status === "pending" || i.status === "opened" || i.status === "started") s.holds.set(`invite:${i.ref}`, HOLD_MICRO);
  return st;
}

const assessment = (s: FakeState): AssessmentState => (s.assessment ??= seedAssessment(s));

/** The candidate finishes and grading ends: results and integrity become readable. */
export function finishInvitation(s: FakeState, ref: string, score = 76, flagged = false): void {
  const i = assessment(s).invites.get(ref);
  if (!i) return;
  Object.assign(i, { status: "completed", ready: true, score, flagged });
  s.holds.delete(`invite:${ref}`);
}

/** Applies approvals that have been decided: revokes and emails take effect. */
function sweep(c: FakeCtx): AssessmentState {
  const st = assessment(c.s);
  for (const i of st.invites.values()) {
    if ((i.status === "pending" || i.status === "opened") && i.expiresAt <= c.now) i.status = "expired";
    const a = i.revokeApproval ? c.s.approvals.get(i.revokeApproval) : undefined;
    if (a?.status === "approved" && i.status !== "revoked") {
      i.status = "revoked";
      i.revokedAt = a.decidedAt ?? c.now;
      c.s.holds.delete(`invite:${i.ref}`);
    } else if (a && a.status !== "pending" && a.status !== "approved") i.revokeApproval = undefined;
    if (i.status === "expired") c.s.holds.delete(`invite:${i.ref}`);
  }
  for (const e of st.emails) {
    if (e.applied || c.s.approvals.get(e.approval)?.status !== "approved") continue;
    e.applied = true;
    st.sent.push({ to: e.to, text: e.text });
    for (const i of st.invites.values()) if (e.to.includes(i.email) && e.text.includes(i.link)) i.emailedAt = c.now;
  }
  return st;
}

const examView = (e: Exam) => ({
  title: e.title,
  ...(e.description ? { description: e.description } : {}),
  durationMinutes: e.durationMinutes,
  ...(e.passScore !== undefined ? { passScore: e.passScore } : {}),
  proctoring: e.proctoring,
  identityRequired: e.identityRequired,
  status: e.status,
});

const inviteView = (i: Invite) => ({
  status: i.status,
  expiresAt: iso(i.expiresAt),
  createdAt: iso(i.createdAt),
  ...(i.emailedAt ? { emailedAt: iso(i.emailedAt) } : {}),
  ...(i.revokedAt ? { revokedAt: iso(i.revokedAt) } : {}),
});

const PRICES: Record<string, number> = {
  "assessment.exam.publish": 13_000,
  "assessment.invitation.create": 13_000 + HOLD_MICRO,
  "assessment.invitation.revoke": 0,
  "email.send": 2_000,
};

const notReady = (c: FakeCtx) => c.fail(404, "not_found", "Not ready yet. Grading is still running; try again in a minute.");

function capability(c: FakeCtx, id: string): Response | undefined {
  const st = sweep(c);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const b = (c.body ?? {}) as Record<string, any>;
  const exam = typeof b.ref === "string" ? st.exams.get(b.ref) : undefined;
  const invite = typeof b.ref === "string" ? st.invites.get(b.ref) : undefined;
  const needExam = () => (exam ? undefined : c.fail(404, "not_found", "No exam with that ref. List yours with assessment.exams.list."));
  const needInvite = () => (invite ? undefined : c.fail(404, "not_found", "No invitation with that ref. List them with assessment.invitations.list."));

  switch (id) {
    case "assessment.exams.list": {
      const rows = [...st.exams.values()].filter((e) => !b.status || e.status === b.status);
      return c.json(200, { results: rows.map((e) => ({ ...examView(e), ref: e.ref, questionCount: e.questions.length })) });
    }
    case "assessment.exam.get":
      return needExam() ?? c.json(200, examView(exam!));
    case "assessment.exam.create": {
      if (!b.title || !b.durationMinutes || !b.proctoring) return c.fail(400, "invalid_request", "Send title, durationMinutes and proctoring.");
      const ref = `exm_fake${String(++st.seq).padStart(4, "0")}`;
      const e: Exam = { ref, title: b.title, description: b.description, durationMinutes: b.durationMinutes, passScore: b.passScore, proctoring: b.proctoring, identityRequired: !!b.identityRequired, status: "draft", questions: [] };
      st.exams.set(ref, e);
      return c.json(200, { ...examView(e), ref });
    }
    case "assessment.question.create": {
      const bad = needExam();
      if (bad) return bad;
      if (exam!.status !== "draft") return c.fail(409, "conflict", "This exam is published, so its questions are frozen.");
      if (!b.text || !b.type || !b.content) return c.fail(400, "invalid_request", "Send text, type and content.");
      exam!.questions.push({ text: b.text, points: b.points, required: b.required, type: b.type, content: b.content, order: exam!.questions.length + 1 });
      return c.json(200, { created: true });
    }
    case "assessment.questions.list":
      return needExam() ?? c.json(200, { results: exam!.questions });
    case "assessment.exam.publish": {
      const bad = needExam();
      if (bad) return bad;
      if (exam!.status !== "draft") return c.fail(409, "conflict", "This exam is already published and cannot go back to draft.");
      if (exam!.questions.length === 0) return c.fail(409, "conflict", "Add at least one question before publishing.");
      exam!.status = "active";
      return c.json(200, { status: "active" });
    }
    case "assessment.invitation.create": {
      const bad = needExam();
      if (bad) return bad;
      const key = c.headers["idempotency-key"];
      if (!key) return c.fail(400, "invalid_request", "Send an Idempotency-Key header: this call needs a retry key.");
      if (exam!.status !== "active") return c.fail(409, "conflict", "Publish the exam before inviting candidates.");
      const prior = st.idem.get(key);
      if (prior) {
        const i = st.invites.get(prior)!;
        return c.json(200, { link: i.link, expiresAt: iso(i.expiresAt), created: false, ref: i.ref });
      }
      const p = platform(c.s);
      const available = p.balanceMicro - [...c.s.holds.values()].reduce((n, x) => n + x, 0);
      if (available < HOLD_MICRO)
        return c.json(402, { error: { code: "spend_cap_reached", reason: "balance", message: "Your balance is too low to hold credit for this session. Add credit, then try again.", effect: "none", top_up: { message: "Add credit, then try again.", links: [{ label: "Add credit", url: "https://app.pramaan.dev/settings/wallet" }], required_micro: HOLD_MICRO, balance_micro: available } } });
      const ref = `inv_fake${String(++st.seq).padStart(4, "0")}`;
      const i: Invite = { ref, examRef: exam!.ref, email: String(b.email), status: "pending", createdAt: c.now, expiresAt: c.now + 10 * DAY, link: `https://tests.example.com/i/${ref}`, ready: false };
      st.invites.set(ref, i);
      st.idem.set(key, ref);
      c.s.holds.set(`invite:${ref}`, HOLD_MICRO);
      return c.json(200, { link: i.link, expiresAt: iso(i.expiresAt), created: true, ref });
    }
    case "assessment.invitations.list": {
      const bad = needExam();
      if (bad) return bad;
      const rows = [...st.invites.values()].filter((i) => i.examRef === exam!.ref && (!b.status || i.status === b.status));
      return c.json(200, { results: rows.sort((x, y) => y.createdAt - x.createdAt).map((i) => ({ ...inviteView(i), ref: i.ref })) });
    }
    case "assessment.invitation.get":
      return needInvite() ?? c.json(200, inviteView(invite!));
    case "assessment.session.get": {
      const bad = needInvite();
      if (bad) return bad;
      const state = invite!.status;
      return c.json(200, {
        environment: "test",
        status: state === "completed" ? "completed" : state === "started" ? "in_progress" : state === "expired" ? "expired" : "invited",
        attemptStatus: state === "completed" ? "graded" : state === "started" ? "in_progress" : state === "expired" ? "expired" : null,
        startedAt: state === "started" || state === "completed" ? iso(invite!.createdAt + 3_600_000) : null,
        completedAt: state === "completed" ? iso(invite!.createdAt + 7_200_000) : null,
        evidenceStatus: invite!.ready ? "complete" : "pending",
      });
    }
    case "assessment.invitation.revoke": {
      const bad = needInvite();
      if (bad) return bad;
      if (invite!.status === "revoked") return c.json(200, { status: "revoked", revokedAt: iso(invite!.revokedAt ?? c.now) });
      if (invite!.status !== "pending" && invite!.status !== "opened")
        return c.fail(409, "conflict", "This candidate already started or the invitation ended, so it can't be withdrawn.");
      invite!.revokeApproval ??= c.addApproval({ capability: id, priceMicro: 0, input: { ref: invite!.ref, email: invite!.email }, requestedBy: { kind: "key" }, createdAt: c.now });
      return c.json(202, { job_id: invite!.revokeApproval, status: "running", held_micro: 0 });
    }
    case "assessment.result.get": {
      const bad = needInvite();
      if (bad) return bad;
      if (!invite!.ready) return notReady(c);
      const score = invite!.score ?? 0;
      const exam2 = st.exams.get(invite!.examRef)!;
      return c.json(200, {
        completedAt: iso(invite!.createdAt + 7_200_000),
        environment: "test",
        grading: exam2.questions.map((q, n) => ({ order: n + 1, question: q.text, method: q.type === "mcq" ? "mcq_sync" : "ai_async", isCorrect: q.type === "mcq" ? true : null, pointsAwarded: q.type === "mcq" ? (q.points ?? 0) : Math.round((q.points ?? 0) * 0.6), pointsPossible: q.points ?? 0, rationale: q.type === "mcq" ? null : "Covers cursors but not stable ordering." })),
        score,
        passed: score >= (exam2.passScore ?? 0),
        gradingStatus: "complete",
        finalizationStatus: "final",
        revision: 1,
        integrityVerdict: invite!.flagged ? "flagged" : "clean",
        proctoringRisk: invite!.flagged ? "high" : "low",
        trustScore: invite!.flagged ? 41 : 93,
      });
    }
    case "assessment.integrity-report.get": {
      const bad = needInvite();
      if (bad) return bad;
      if (!invite!.ready) return notReady(c);
      return c.json(200, {
        finalizedAt: iso(invite!.createdAt + 7_300_000),
        revision: { status: "current", isCurrent: true },
        verdict: invite!.flagged ? "flagged" : "clean",
        integrityScore: invite!.flagged ? 41 : 93,
        signals: invite!.flagged
          ? [{ type: "tab_switch", severity: "high", count: 9 }, { type: "multiple_faces", severity: "critical", count: 2 }]
          : [{ type: "tab_switch", severity: "low", count: 1 }],
        coverage: { heartbeatPct: 98, evidenceComplete: true, sufficient: true },
      });
    }
    case "email.send": {
      const to = ([] as string[]).concat(b.to ?? []);
      if (to.length === 0 || !b.subject) return c.fail(400, "invalid_request", "Send to and subject.");
      if (b.sender === "domain" && !b.from) return c.fail(400, "invalid_request", 'With sender "domain", send a from address on a domain you verified.');
      const key = c.headers["idempotency-key"];
      const prior = key ? st.idem.get(`mail:${key}`) : undefined;
      if (prior) return c.json(202, { job_id: prior, status: "running", held_micro: 0 });
      const approval = c.addApproval({ capability: id, priceMicro: PRICES[id], input: b, requestedBy: { kind: "key" }, createdAt: c.now });
      if (key) st.idem.set(`mail:${key}`, approval);
      st.emails.push({ approval, to, text: String(b.text ?? ""), applied: false });
      return c.json(202, { job_id: approval, status: "running", held_micro: 0 });
    }
  }
  return undefined;
}

/** The assessment routes of this fake. Returns undefined for a route it doesn't serve. */
export function assessmentRoutes(c: FakeCtx): Response | undefined {
  const m = c.path.match(/^\/v1\/capabilities\/([^/]+?)(\/estimate)?$/);
  if (c.method !== "POST" || !m) return undefined;
  const id = decodeURIComponent(m[1]);
  if (m[2]) return id in PRICES ? c.json(200, { price_max_micro: PRICES[id] }) : undefined;
  return capability(c, id);
}

/** The emails that went out after approval, for tests. */
export const sentEmails = (s: FakeState) => sweepAll(s).sent;

function sweepAll(s: FakeState): AssessmentState {
  // Same as a route call: applies decided approvals before reading.
  const noop = (): Response => new Response(null);
  return sweep({ s, method: "GET", path: "", url: new URL("http://fake"), headers: {}, body: undefined, now: s.now(), json: noop, fail: noop, addApproval: () => "" });
}

/** Invitations and emails, brought up to date, for tests that read state directly. */
export const assessmentState = sweepAll;

import type { FakeCtx, FakeState } from "./fake";

// Fake private memories (memory.* superpowers) and the organisation memory queue, with the documented
// shapes. Extends the core fake. Deleting a memory, or erasing a whole scope, waits for a member's
// approval in the approvals inbox, as an irreversible call made with a key does, and takes effect
// once it is approved.
//
// Not in the OpenAPI: the organisation queue lives under /v1/internal/memory/admin, which
// the real API opens to a signed-in admin session only. The fake lets a key send `Pramaan-Member`.

const DAY = 86_400_000;

interface Item {
  ref: string;
  user: string;
  text: string;
  createdAt: number;
  deleteApproval?: string;
}

interface Change {
  ref: string;
  user: string;
  event: "add" | "update" | "delete";
  text?: string;
  at: number;
}

interface OrgRow {
  id: string;
  text: string;
  kind: "org_candidate" | "org";
  status: "active" | "review" | "rejected";
  autoPromotedAt?: number;
  noticeReadAt?: number;
}

export interface MemoryState {
  items: Item[];
  changes: Change[];
  org: OrgRow[];
  eraseApprovals: Map<string, string>;
  seq: number;
}

const ref = (n: number) => `rh_mem${String(n).padStart(21, "0")}`;

function seedMemory(s: FakeState): MemoryState {
  const now = s.now();
  const m: MemoryState = { items: [], changes: [], org: [], eraseApprovals: new Map(), seq: 0 };
  const add = (user: string, text: string, ago: number) => {
    const item = { ref: ref(++m.seq), user, text, createdAt: now - ago * DAY };
    m.items.push(item);
    m.changes.push({ ref: item.ref, user, event: "add", text, at: item.createdAt });
  };
  add("user-42", "Prefers short emails with the answer in the first line.", 40);
  add("user-42", "Works as a product designer at a small company.", 33);
  add("user-42", "Likes a weekly summary on Monday mornings.", 21);
  add("user-42", "Is vegetarian and allergic to peanuts.", 9);
  add("user-42", "Is planning a trip to Lisbon in March.", 2);
  add("user-7", "Another person's private note that nobody else should ever see.", 5);
  m.org.push(
    { id: "mi_org_cand1", text: "The team writes customer emails in a friendly, plain tone.", kind: "org_candidate", status: "active" },
    { id: "mi_org_cand2", text: "Invoices are sent on the first working day of the month.", kind: "org_candidate", status: "review" },
    { id: "mi_org_auto1", text: "Support replies go out within one working day.", kind: "org", status: "active", autoPromotedAt: now - DAY },
  );
  return m;
}

export const memory = (s: FakeState): MemoryState => (s.memory ??= seedMemory(s));

/** Adds a memory for a person (what chats do over time). */
export function addFakeMemory(s: FakeState, user: string, text: string): string {
  const m = memory(s);
  const item = { ref: ref(++m.seq), user, text, createdAt: s.now() };
  m.items.push(item);
  m.changes.push({ ref: item.ref, user, event: "add", text, at: item.createdAt });
  return item.ref;
}

const iso = (ms: number) => new Date(ms).toISOString();

/** Applies approvals that have been decided: deletes and erases take effect. */
function sweep(c: FakeCtx): MemoryState {
  const m = memory(c.s);
  const drop = (item: Item, at: number) => {
    m.items.splice(m.items.indexOf(item), 1);
    m.changes.push({ ref: item.ref, user: item.user, event: "delete", text: item.text, at });
  };
  for (const item of [...m.items]) {
    const a = item.deleteApproval ? c.s.approvals.get(item.deleteApproval) : undefined;
    if (a?.status === "approved") drop(item, a.decidedAt ?? c.now);
    else if (a && a.status !== "pending") item.deleteApproval = undefined;
  }
  for (const [user, id] of [...m.eraseApprovals]) {
    const a = c.s.approvals.get(id);
    if (a?.status === "approved") {
      for (const item of m.items.filter((x) => x.user === user)) drop(item, a.decidedAt ?? c.now);
      m.eraseApprovals.delete(user);
    } else if (a && a.status !== "pending") m.eraseApprovals.delete(user);
  }
  return m;
}

const row = (i: Item) => ({ ref: i.ref, text: i.text, createdAt: iso(i.createdAt), updatedAt: iso(i.createdAt) });

function page<T>(c: FakeCtx, rows: T[], b: Record<string, unknown>) {
  const limit = Math.min(50, Math.max(1, Number(b.limit) || 10));
  const start = typeof b.cursor === "string" ? Number(b.cursor) || 0 : 0;
  const next = start + limit;
  return c.json(200, { results: rows.slice(start, next), ...(next < rows.length ? { nextCursor: String(next) } : {}) });
}

function capability(c: FakeCtx, id: string): Response | undefined {
  if (!id.startsWith("memory.")) return undefined;
  const m = sweep(c);
  const b = (c.body ?? {}) as Record<string, unknown>;
  const scope = b.scope as { namespace?: unknown; user?: unknown } | undefined;
  const needsScope = ["memory.items.list", "memory.items.search", "memory.history.list", "memory.scope.delete"].includes(id);
  if (needsScope && (!scope || typeof scope.namespace !== "string" || scope.namespace === ""))
    return c.fail(400, "invalid_request", "scope.namespace is required: the name of the memory set.");
  const user = typeof scope?.user === "string" ? scope.user : "";
  const mine = () => m.items.filter((i) => i.user === user && user !== "");
  const owned = () => m.items.find((i) => i.ref === b.ref && i.user === user && user !== "");
  const noItem = () => c.fail(404, "not_found", "No such memory. List them with memory.items.list.");
  // Reading or deleting one fact names it by ref only; ownership comes from the user in the scope.
  const needsUser = (id === "memory.item.get" || id === "memory.item.delete") && !(b.scope as { user?: unknown } | undefined)?.user;
  if (needsUser) return c.fail(400, "invalid_request", "scope.user is required: your end user's logical identifier.");

  switch (id) {
    case "memory.items.list": {
      const words = typeof b.keywords === "string" ? b.keywords.toLowerCase().split(/\s+/).filter(Boolean) : [];
      const rows = mine().filter((i) => words.every((w) => i.text.toLowerCase().includes(w))).sort((a, z) => z.createdAt - a.createdAt);
      return page(c, rows.map(row), b);
    }
    case "memory.items.search": {
      if (typeof b.query !== "string" || b.query.trim() === "") return c.fail(400, "invalid_request", "query is required: what to look for.");
      const words = b.query.toLowerCase().split(/\s+/).filter(Boolean);
      const rows = mine().filter((i) => words.some((w) => i.text.toLowerCase().includes(w)));
      return page(c, rows.map((i) => ({ ...row(i), similarity: 0.9 })), b);
    }
    case "memory.item.get": {
      const item = owned();
      return item ? c.json(200, { found: true, item: row(item) }) : noItem();
    }
    case "memory.item.delete": {
      const item = owned();
      if (!item) return noItem();
      if (b.confirm !== true) return c.fail(400, "invalid_request", "Send confirm: true to delete this memory for good.");
      item.deleteApproval ??= c.addApproval({ capability: id, priceMicro: 0, input: { ref: item.ref }, requestedBy: { kind: "key" }, createdAt: c.now });
      return c.json(202, { job_id: item.deleteApproval, status: "running", held_micro: 0 });
    }
    case "memory.scope.delete": {
      if (!user) return c.fail(400, "invalid_request", "scope.user is required to erase one person's memories.");
      if (b.confirm !== true) return c.fail(400, "invalid_request", "Send confirm: true to erase these memories for good.");
      if (mine().length === 0) return c.json(200, { deletedCount: 0 });
      const approval = m.eraseApprovals.get(user) ?? c.addApproval({ capability: id, priceMicro: 0, input: { scope: b.scope }, requestedBy: { kind: "key" }, createdAt: c.now });
      m.eraseApprovals.set(user, approval);
      return c.json(202, { job_id: approval, status: "running", held_micro: 0 });
    }
    case "memory.history.list": {
      const rows = m.changes.filter((x) => x.user === user && user !== "").sort((a, z) => z.at - a.at);
      return page(c, rows.map((x) => ({ ref: x.ref, event: x.event, ...(x.text ? { text: x.text } : {}), createdAt: iso(x.at) })), b);
    }
  }
  return c.fail(404, "not_found", "No capability with that id. List them with GET /v1/capabilities.");
}

const isAdmin = (c: FakeCtx) => {
  const member = c.s.members.find((x) => x.member_id === c.headers["pramaan-member"]);
  return member?.role === "owner" || member?.role === "admin";
};

function admin(c: FakeCtx): Response | undefined {
  const m = memory(c.s);
  if (c.method === "GET" && c.path === "/v1/internal/memory/admin/queue") {
    if (!isAdmin(c)) return c.fail(403, "forbidden", "Only workspace admins can manage org memory. Ask an admin to sign in.");
    return c.json(200, {
      enabled: true,
      rows: m.org.filter((o) => o.kind === "org_candidate" && (o.status === "active" || o.status === "review")).map((o) => ({ id: o.id, text: o.text, conflict: o.status === "review" })),
      notices: m.org.filter((o) => o.kind === "org" && o.status === "active" && o.autoPromotedAt && !o.noticeReadAt).map((o) => ({ id: o.id, text: o.text, promotedAt: iso(o.autoPromotedAt!) })),
    });
  }
  if (c.method === "POST" && c.path === "/v1/internal/memory/admin/decide") {
    if (!isAdmin(c)) return c.fail(403, "forbidden", "Only workspace admins can manage org memory. Ask an admin to sign in.");
    const b = (c.body ?? {}) as { id?: unknown; action?: unknown };
    if (typeof b.id !== "string" || !["approve", "reject", "remove", "acknowledge"].includes(String(b.action)))
      return c.fail(400, "invalid_request", "Send a memory id and approve, reject, remove or acknowledge, then retry.");
    const o = m.org.find((x) => x.id === b.id);
    if (!o) return c.fail(404, "not_found", "Org memory not found. Reload the queue and retry.");
    if (b.action === "reject" && o.kind !== "org_candidate") return c.fail(400, "invalid_request", "Only candidates can be rejected. Use remove for org memory.");
    if (b.action === "approve") Object.assign(o, { kind: "org", status: "active", noticeReadAt: c.now });
    else if (b.action === "acknowledge") o.noticeReadAt = c.now;
    else o.status = "rejected";
    return c.json(200, { ok: true });
  }
  return undefined;
}

/** The memory routes of this fake. Returns undefined for a route it doesn't serve. */
export function memoryRoutes(c: FakeCtx): Response | undefined {
  const m = c.path.match(/^\/v1\/capabilities\/([^/]+)$/);
  if (c.method === "POST" && m) return capability(c, decodeURIComponent(m[1]));
  return admin(c);
}

import type { FakeCtx, FakeState } from "./fake";

// Fake opt-out lists (messaging.opt-out* superpowers), with the documented shapes and the API's own
// messages. Extends the core fake. Addresses are stored whole but only a masked hint is ever
// returned, as the API does. An entry the person made themselves (a STOP reply or an unsubscribe
// link) can't be removed by the project.

const DAY = 86_400_000;
const CHANNELS = ["sms", "whatsapp", "voice", "email"];

interface Entry {
  id: string;
  address: string;
  channel: string;
  source: "builder_api" | "inbound_stop" | "unsubscribe_link";
  reason?: string;
  createdAt: number;
}

export interface ConsentState {
  entries: Entry[];
  stops: { stopId: string; addressHint: string; sendingNumberHint: string; channel: string; createdAt: number }[];
  seq: number;
}

const hint = (a: string) => `${a.slice(0, 3)}…${a.slice(-2)}`;

function seedConsent(s: FakeState): ConsentState {
  const now = s.now();
  const st: ConsentState = { entries: [], stops: [], seq: 0 };
  const add = (address: string, channel: string, source: Entry["source"], ago: number, reason?: string) =>
    st.entries.push({ id: `opt_FAKE${String(++st.seq).padStart(22, "0")}`, address, channel, source, createdAt: now - ago * DAY, ...(reason ? { reason } : {}) });
  add("+14155550100", "sms", "builder_api", 30, "Asked by phone");
  add("pat@example.com", "email", "unsubscribe_link", 12);
  add("+442071838750", "all", "builder_api", 3, "Asked to stop all contact");
  st.stops.push({ stopId: "stop_FAKE0001", addressHint: "+44…77", sendingNumberHint: "+14…21", channel: "sms", createdAt: now - 6 * DAY });
  return st;
}

export const consent = (s: FakeState): ConsentState => (s.consent ??= seedConsent(s));

/** The same normal form the API keeps: an email lower-cased, a phone number as +digits. */
function normalise(raw: unknown): string | undefined {
  if (typeof raw !== "string") return undefined;
  const v = raw.trim();
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return v.toLowerCase();
  const phone = v.replace(/[\s().-]/g, "");
  return /^\+[1-9]\d{6,14}$/.test(phone) ? phone : undefined;
}

const iso = (ms: number) => new Date(ms).toISOString();
const view = (e: Entry) => ({ optOutId: e.id, addressHint: hint(e.address), channel: e.channel, source: e.source, ...(e.reason ? { reason: e.reason } : {}), createdAt: iso(e.createdAt) });

const BAD_ADDRESS = "address must be a phone number with its country code (like +14155550100) or an email address.";

function capability(c: FakeCtx, id: string): Response | undefined {
  if (!id.startsWith("messaging.opt-out")) return undefined;
  const st = consent(c.s);
  const b = (c.body ?? {}) as Record<string, unknown>;
  if (id === "messaging.opt-outs.list") {
    const limit = Math.min(100, Math.max(1, Number(b.limit) || 50));
    const start = typeof b.cursor === "string" ? Number(b.cursor) || 0 : 0;
    const rows = [...st.entries].sort((x, y) => x.createdAt - y.createdAt);
    const next = start + limit;
    return c.json(200, {
      results: rows.slice(start, next).map(view),
      ...(next < rows.length ? { nextCursor: String(next) } : {}),
      ...(start === 0 ? { organisationStops: st.stops.map((x) => ({ ...x, source: "inbound_stop", createdAt: iso(x.createdAt) })) } : {}),
    });
  }
  const address = normalise(b.address);
  if (!address) return c.fail(400, "invalid_request", BAD_ADDRESS);
  const email = address.includes("@");
  if (id === "messaging.opt-out.check") {
    if (!CHANNELS.includes(String(b.channel))) return c.fail(400, "invalid_request", "channel must be sms, whatsapp, voice or email.");
    const blocked = st.entries.some((e) => e.address === address && (e.channel === "all" || e.channel === b.channel)) || st.stops.some((x) => hint(address) === x.addressHint && x.channel === b.channel);
    return c.json(200, { blocked });
  }
  if (id === "messaging.opt-out.add") {
    const channel = b.channel === undefined ? "all" : String(b.channel);
    if (![...CHANNELS, "all"].includes(channel)) return c.fail(400, "invalid_request", "channel must be sms, whatsapp, voice, email or all.");
    if (email && channel === "sms") return c.fail(400, "invalid_request", "An email address can only be blocked on email or all.");
    const existing = st.entries.find((e) => e.address === address && e.channel === channel);
    if (existing) return c.json(200, view(existing));
    const entry: Entry = { id: `opt_FAKE${String(++st.seq).padStart(22, "0")}`, address, channel, source: "builder_api", createdAt: c.now, ...(typeof b.reason === "string" && b.reason ? { reason: b.reason.slice(0, 200) } : {}) };
    st.entries.push(entry);
    return c.json(200, view(entry));
  }
  if (id === "messaging.opt-out.remove") {
    if (b.confirm !== true) return c.fail(400, "invalid_request", "Send confirm: true to confirm that this person may be messaged again.");
    const gone = st.entries.filter((e) => e.address === address && e.source === "builder_api" && (b.channel === undefined || e.channel === b.channel));
    st.entries = st.entries.filter((e) => !gone.includes(e));
    return c.json(200, { removed: gone.length });
  }
  return c.fail(404, "not_found", "No capability with that id. List them with GET /v1/capabilities.");
}

/** The consent routes of this fake. Returns undefined for a route it doesn't serve. */
export function consentRoutes(c: FakeCtx): Response | undefined {
  const m = c.path.match(/^\/v1\/capabilities\/([^/]+)$/);
  return c.method === "POST" && m ? capability(c, decodeURIComponent(m[1])) : undefined;
}

import type { FakeCtx, FakeState } from "./fake";

// Fake per-call rows and webhook deliveries: the activity log's routes. NOT in the real API yet
// GET /v1/calls, GET /v1/calls/{id} and GET /v1/webhook-deliveries are proposed shapes,
// served here so the block can be built and tested. The real API answers 404 for them today and
// the block falls back to the daily totals of GET /v1/usage.

const DAY = 86_400_000;

interface Call {
  call_id: string;
  capability: string;
  status: "done" | "failed" | "running" | "waiting_approval";
  charged_micro: number;
  created_at: number;
  error?: { code: string; message: string; next?: string };
}

interface Delivery {
  delivery_id: string;
  event: string;
  status: "delivered" | "failed" | "retrying";
  attempts: number;
  response_status?: number;
  created_at: number;
  error?: { message: string; next?: string };
}

export interface ActivityState {
  calls: Call[];
  deliveries: Delivery[];
}

const CAPS: [string, number][] = [["web.search", 5_000], ["email.send", 2_000], ["llm.complete", 12_000], ["sms.send", 9_100], ["web.read", 4_000]];
const ERRORS: Record<string, { code: string; message: string; next: string }> = {
  "email.send": { code: "connection_required", message: "Your Gmail connection has expired, so the email was not sent.", next: "Reconnect Gmail in Connections, then send it again." },
  "sms.send": { code: "opted_out", message: "This person opted out of text messages, so nothing was sent and nothing was charged.", next: "Remove them from your text list only if they asked to hear from you again." },
  "web.read": { code: "upstream_unavailable", message: "That page could not be reached.", next: "Check the address and try again in a minute." },
};

function seedActivity(s: FakeState): ActivityState {
  const now = s.now();
  const calls: Call[] = [];
  for (let i = 0; i < 40; i++) {
    const [capability, price] = CAPS[i % CAPS.length];
    const failed = i % 7 === 3 && ERRORS[capability] !== undefined;
    const status: Call["status"] = i === 0 ? "running" : i === 1 ? "waiting_approval" : failed ? "failed" : "done";
    calls.push({
      call_id: `call_fake${String(i + 1).padStart(4, "0")}`,
      capability,
      status,
      charged_micro: status === "done" ? price : 0,
      created_at: now - i * 7 * 3_600_000,
      ...(status === "failed" ? { error: ERRORS[capability] } : {}),
    });
  }
  const deliveries: Delivery[] = [
    { delivery_id: "whd_fake0001", event: "approval.decided", status: "delivered", attempts: 1, response_status: 200, created_at: now - 2 * 3_600_000 },
    { delivery_id: "whd_fake0002", event: "job.finished", status: "failed", attempts: 5, response_status: 500, created_at: now - DAY, error: { message: "Your server answered 500 five times, so we stopped trying.", next: "Fix the error on your server, then replay the event from your dashboard." } },
    { delivery_id: "whd_fake0003", event: "job.finished", status: "retrying", attempts: 2, response_status: 503, created_at: now - 20 * 60_000 },
    { delivery_id: "whd_fake0004", event: "approval.requested", status: "delivered", attempts: 1, response_status: 200, created_at: now - 3 * DAY },
  ];
  return { calls, deliveries };
}

export const activity = (s: FakeState): ActivityState => (s.activity ??= seedActivity(s));

const iso = (ms: number) => new Date(ms).toISOString();
const callView = (x: Call) => ({ ...x, created_at: iso(x.created_at) });
const day = (ms: number) => iso(ms).slice(0, 10);

/** The activity routes of this fake. Returns undefined for a route it doesn't serve. */
export function activityRoutes(c: FakeCtx): Response | undefined {
  if (c.method !== "GET") return undefined;
  const a = activity(c.s);
  const q = c.url.searchParams;
  if (c.path === "/v1/calls") {
    const from = q.get("from");
    const to = q.get("to");
    const rows = a.calls
      .filter((x) => (!q.get("capability") || x.capability === q.get("capability")) && (!q.get("status") || x.status === q.get("status")) && (!from || day(x.created_at) >= from) && (!to || day(x.created_at) <= to))
      .sort((x, y) => y.created_at - x.created_at);
    const limit = Math.min(100, Math.max(1, Number(q.get("limit")) || 20));
    const start = Number(q.get("cursor")) || 0;
    const next = start + limit;
    return c.json(200, { results: rows.slice(start, next).map(callView), ...(next < rows.length ? { next_cursor: String(next) } : {}) });
  }
  const m = c.path.match(/^\/v1\/calls\/([^/]+)$/);
  if (m) {
    const call = a.calls.find((x) => x.call_id === decodeURIComponent(m[1]));
    return call ? c.json(200, callView(call)) : c.fail(404, "not_found", "No call with that id. List them with GET /v1/calls.");
  }
  if (c.path === "/v1/webhook-deliveries")
    return c.json(200, { results: [...a.deliveries].sort((x, y) => y.created_at - x.created_at).map((d) => ({ ...d, created_at: iso(d.created_at) })) });
  return undefined;
}

import type { FakeCtx } from "./fake";
import { platform } from "./fake-platform";

// A small fake catalogue of single actions ("superpowers"): search with a clarify question and near
// misses, a described capability with its request schema, an estimate, and a run. Actions that send
// something wait for a member's approval in the approvals inbox, as a call made with a key does.
// Extends the core fake; email.send runs in fake-assessment.ts, which answers first.

type Schema = { type: "object"; required?: string[]; properties: Record<string, Record<string, unknown>> };

interface Cap {
  id: string;
  description: string;
  effect_class: string;
  price_estimate_micro: number;
  requires_approval?: true;
  schema: Schema;
  run?(input: Record<string, unknown>): unknown;
}

const CAPS: Cap[] = [
  {
    id: "web.search",
    description: "Searches the web and returns the top results with a short snippet.",
    effect_class: "read_only",
    price_estimate_micro: 5_000,
    schema: { type: "object", required: ["query"], properties: { query: { type: "string", maxLength: 500, description: "What to search for." } } },
    run: (i) => ({ results: [{ title: `Results for ${String(i.query)}`, url: "https://example.com/a", snippet: "A short summary of the first result." }, { title: "Another source", url: "https://example.com/b", snippet: "A second, shorter summary." }] }),
  },
  {
    id: "web.read",
    description: "Reads one web page and returns its text.",
    effect_class: "read_only",
    price_estimate_micro: 4_000,
    schema: { type: "object", required: ["url"], properties: { url: { type: "string", maxLength: 2048, description: "The page to read, starting with https://." } } },
    run: (i) => ({ title: "Example page", text: `The text of ${String(i.url)}.` }),
  },
  {
    id: "llm.complete",
    description: "Writes text from an instruction.",
    effect_class: "read_only",
    price_estimate_micro: 12_000,
    schema: {
      type: "object",
      required: ["prompt"],
      properties: {
        prompt: { type: "string", maxLength: 4000, description: "What to write." },
        maxWords: { type: "integer", minimum: 1, maximum: 500, description: "Longest answer, in words." },
      },
    },
    run: (i) => ({ text: `Here is a draft for: ${String(i.prompt)}` }),
  },
  {
    id: "email.send",
    description: "Sends one email from your connected inbox.",
    effect_class: "external_irreversible",
    price_estimate_micro: 2_000,
    requires_approval: true,
    schema: {
      type: "object",
      required: ["to", "subject", "text"],
      properties: {
        to: { type: "string", maxLength: 320, description: "Who to send it to." },
        subject: { type: "string", maxLength: 300 },
        text: { type: "string", maxLength: 10000, description: "The message." },
      },
    },
  },
  {
    id: "sms.send",
    description: "Sends a text message to one phone number.",
    effect_class: "external_irreversible",
    price_estimate_micro: 9_100,
    requires_approval: true,
    schema: {
      type: "object",
      required: ["to", "text"],
      properties: {
        to: { type: "string", maxLength: 32, description: "The phone number, with country code." },
        text: { type: "string", maxLength: 1600, description: "The message." },
      },
    },
  },
];

const info = (c: Cap) => ({
  id: c.id,
  description: c.description,
  effect_class: c.effect_class,
  mode: "sync",
  price_estimate_micro: c.price_estimate_micro,
  available: true,
  needs_connection: false,
  ...(c.requires_approval ? { requires_approval: true } : {}),
});

/** The fuller answer for GET /v1/capabilities/{id}. */
export function catalogueDescribe(id: string) {
  const c = CAPS.find((x) => x.id === id);
  return c ? { ...info(c), request_schema: c.schema, result_schema: { type: "object" } } : undefined;
}

const words = (q: string) => q.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);

function search(c: FakeCtx, query: string): Response {
  const q = words(query);
  if (q.length === 0) return c.json(200, { results: CAPS.map(info) });
  const scored = CAPS.map((cap) => {
    const text = `${cap.id.replace(/[._-]/g, " ")} ${cap.description}`.toLowerCase();
    return { cap, score: q.filter((w) => text.includes(w)).length };
  })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score);
  if (scored.length === 0) return c.json(200, { results: [], near_misses: [{ missed: q }] });
  // Two sends that tie: ask which one is meant.
  const tied = scored.filter((x) => x.score === scored[0].score && /\.send$/.test(x.cap.id));
  const clarify =
    q.includes("send") && !q.some((w) => ["email", "mail", "text", "sms"].includes(w)) && tied.length > 1
      ? { question: "Do you want to send an email or a text message?", options: [{ id: "email.send", label: "Send an email" }, { id: "sms.send", label: "Send a text message" }] }
      : undefined;
  return c.json(200, { results: scored.map((x) => info(x.cap)), ...(clarify ? { clarify } : {}) });
}

function problem(cap: Cap, input: Record<string, unknown>): string | undefined {
  for (const key of cap.schema.required ?? []) {
    const v = input[key];
    if (typeof v !== "string" || v.trim() === "") return `${key} is required: ${String(cap.schema.properties[key]?.description ?? "send a value").replace(/\.$/, "").toLowerCase()}.`;
  }
  return undefined;
}

/** The catalogue routes of this fake. Returns undefined for a route it doesn't serve. */
export function catalogueRoutes(c: FakeCtx): Response | undefined {
  if (c.method === "GET" && c.path === "/v1/capabilities") return search(c, c.url.searchParams.get("query") ?? "");
  const m = c.path.match(/^\/v1\/capabilities\/([^/]+?)(\/estimate)?$/);
  if (c.method !== "POST" || !m) return undefined;
  const cap = CAPS.find((x) => x.id === decodeURIComponent(m[1]));
  if (!cap) return undefined;
  const input = (c.body ?? {}) as Record<string, unknown>;
  const bad = problem(cap, input);
  if (m[2]) {
    const available = platform(c.s).balanceMicro - [...c.s.holds.values()].reduce((n, x) => n + x, 0);
    return c.json(200, { price_max_micro: cap.price_estimate_micro, ready: !bad, can_run: !bad && available >= cap.price_estimate_micro, ...(bad ? { message: bad } : {}) });
  }
  if (bad) return c.fail(400, "invalid_request", bad);
  if (cap.requires_approval) {
    const p = platform(c.s);
    const key = c.headers["idempotency-key"];
    const prior = key ? p.idem.get(`cat:${cap.id}:${key}`) : undefined;
    const approval = prior ?? c.addApproval({ capability: cap.id, priceMicro: cap.price_estimate_micro, input, requestedBy: { kind: "key" }, createdAt: c.now });
    if (key) p.idem.set(`cat:${cap.id}:${key}`, approval);
    return c.json(202, { job_id: approval, status: "running", held_micro: 0 });
  }
  return c.json(200, cap.run!(input));
}

import type { FakeCtx, FakeState } from "./fake";
import { platform } from "./fake-platform";

// Fake provider-screen capabilities for the wave 3 blocks (checkout, payouts, identity, voice,
// booking, e-sign, upload, chat, account, subscriptions), with the documented shapes and the API's
// own style of message. Extends the core fake. Where a provider's own screen would load, the blocks
// show a marked stand-in; the demo's /api/demo route finishes things the outside world would.

export interface Wave3State {
  seq: number;
  idem: Map<string, string>;
  checkouts: Map<string, { ref: string; status: string; amount: number; currency: string; successUrl: string }>;
  /** The seller's payment account. `hosted` is an older account that onboards on a hosted page. */
  verifications: Map<string, { ref: string; status: string; checks: { check: string; status?: string; warnings: string[] }[] }>;
  account: { status: "ready" | "pending" | "restricted"; due: string[]; hosted: boolean; connected: boolean };
  voice?: VoiceState;
  calendar?: CalendarState;
}

export const wave3 = (s: FakeState): Wave3State =>
  (s.wave3 ??= { seq: 0, idem: new Map(), checkouts: new Map(), verifications: new Map(), account: { status: "pending", due: ["external_account", "business_profile.url"], hosted: false, connected: false } });
export const nextId = (s: FakeState, prefix: string) => `${prefix}_FAKE${String(++wave3(s).seq).padStart(6, "0")}`;

type Body = Record<string, unknown>;
type Handler = (c: FakeCtx, b: Body) => Response;

const handlers: Record<string, Handler> = {};

// ---- checkout (payments.checkout.*) ----

const CURRENCY = /^[a-z]{3}$/;

handlers["payments.checkout.create"] = (c, b) => {
  const items = b.lineItems;
  if (!Array.isArray(items) || items.length < 1 || items.length > 100) return c.fail(400, "invalid_request", "lineItems must hold 1 to 100 items.");
  let total = 0;
  for (const it of items as Body[]) {
    if (typeof it.name !== "string" || it.name.trim() === "") return c.fail(400, "invalid_request", "Every item needs a name.");
    if (!Number.isInteger(it.amount) || (it.amount as number) < 1) return c.fail(400, "invalid_request", "Every amount must be a whole number of cents, at least 1.");
    if (typeof it.currency !== "string" || !CURRENCY.test(it.currency) || it.currency !== (items[0] as Body).currency) return c.fail(400, "invalid_request", "Every item must use the same three-letter lowercase currency.");
    total += (it.amount as number) * ((it.quantity as number) || 1);
  }
  if (typeof b.successUrl !== "string" || typeof b.cancelUrl !== "string") return c.fail(400, "invalid_request", "successUrl and cancelUrl are required.");
  const ref = nextId(c.s, "ref");
  wave3(c.s).checkouts.set(ref, { ref, status: "unpaid", amount: total, currency: (items[0] as Body).currency as string, successUrl: b.successUrl });
  // The stand-in page lives in the app that asked, as the hosted page lives at the provider.
  return c.json(200, { ref, checkoutUrl: `${new URL(b.successUrl).origin}/checkout/stand-in?ref=${ref}`, expiresAt: new Date(c.now + 24 * 3_600_000).toISOString() });
};

handlers["payments.checkout.get"] = (c, b) => {
  const k = wave3(c.s).checkouts.get(String(b.ref));
  if (!k) return c.fail(404, "not_found", "Checkout not found. Check the ref.");
  return c.json(200, { status: k.status, payments: k.status === "paid" ? [{ ref: nextId(c.s, "ref"), status: "captured", amount: { amount: k.amount, currency: k.currency } }] : [] });
};

// ---- payouts (payments.account.*) ----

const REQUIRED = ["account_onboarding", "account_management", "notification_banner"];
const COMPONENTS = [...REQUIRED, "payouts", "payments", "balances", "documents"];

handlers["payments.account.connect"] = (c, b) => {
  if (typeof b.returnUrl !== "string" || typeof b.refreshUrl !== "string") return c.fail(400, "invalid_request", "returnUrl and refreshUrl are required.");
  const a = wave3(c.s).account;
  a.connected = true;
  return c.json(200, a.hosted ? { onboardingUrl: "https://onboarding.fake/setup#abc" } : { onboardingMode: "embedded", nextCapability: "payments.account.session.create" });
};

handlers["payments.account.session.create"] = (c, b) => {
  const asked = b.components === undefined ? [] : b.components;
  if (!Array.isArray(asked) || asked.some((x) => !COMPONENTS.includes(String(x)))) return c.fail(400, "invalid_request", `components must be among ${COMPONENTS.join(", ")}.`);
  if (!wave3(c.s).account.connected) return c.fail(409, "conflict", "No payment account yet. Call payments.account.connect first.");
  return c.json(200, {
    clientSecret: `fake_secret_${nextId(c.s, "s")}`,
    publishableKey: "pk_test_FAKE1",
    expiresAt: new Date(c.now + 3_600_000).toISOString(),
    components: [...new Set([...REQUIRED, ...(asked as string[])])],
  });
};

handlers["payments.account.status"] = (c) => {
  const { status, due } = wave3(c.s).account;
  return c.json(200, { status, chargesEnabled: status === "ready", payoutsEnabled: status === "ready", detailsSubmitted: due.length === 0, requirementsDue: due });
};

/** The seller finishes (or is blocked in) the provider's setup screen. */
export function setFakeAccount(s: FakeState, a: Partial<Wave3State["account"]>): void {
  const acc = wave3(s).account;
  Object.assign(acc, a, a.status === "ready" ? { due: [] } : {});
}

// ---- identity check (identity.verification.*) ----

handlers["identity.verification.create"] = (c, b) => {
  if (b.endUserId !== undefined && (typeof b.endUserId !== "string" || b.endUserId.length > 256)) return c.fail(400, "invalid_request", "endUserId must be text of up to 256 characters.");
  if (b.language !== undefined && !/^[a-z]{2}(-[A-Z]{2})?$/.test(String(b.language))) return c.fail(400, "invalid_request", "language must be one of the supported ISO 639-1 codes.");
  const ref = nextId(c.s, "ref");
  wave3(c.s).verifications.set(ref, { ref, status: "not_started", checks: [] });
  // The hosted screen lives with the provider; the demo app stands in for it.
  return c.json(200, { verificationUrl: `/identity/stand-in?ref=${ref}`, sessionNumber: wave3(c.s).verifications.size, status: "not_started", ref });
};

handlers["identity.verification.get"] = (c, b) => {
  const v = wave3(c.s).verifications.get(String(b.ref));
  if (!v) return c.fail(404, "not_found", "Verification not found. Check the ref.");
  // Like the real answer, it carries personal facts; the block must not pass them on.
  return c.json(200, { status: v.status, name: "Ada Lovelace", dateOfBirth: "1990-12-10", documentNumber: "X1234567", checks: v.checks });
};

/** The person finishes (or abandons) the provider's screen. */
export function finishFakeVerification(s: FakeState, ref: string, status: "approved" | "declined" | "in_review" | "in_progress"): void {
  const v = wave3(s).verifications.get(ref);
  if (!v) return;
  v.status = status;
  const row = (check: string, ok: boolean) => ({ check, status: ok ? "passed" : "failed", warnings: ok ? [] : ["MULTIPLE_FACES_DETECTED"] });
  v.checks = status === "in_progress" ? [] : [row("document", true), row("liveness", status !== "declined"), row("face_match", status === "approved")];
  if (status === "in_review") v.checks[2] = { check: "face_match", status: "review", warnings: [] };
}

/** The customer pays (or backs out) on the provider's page: what the stand-in's buttons do. */
export function finishFakeCheckout(s: FakeState, ref: string, status: "paid" | "cancelled"): string | undefined {
  const k = wave3(s).checkouts.get(ref);
  if (!k) return undefined;
  k.status = status;
  return k.successUrl;
}

// ---- chat, account and subscriptions: llm.chat, approval jobs, members/me, organization, billing.* ----

export interface FakeSub {
  subscriptionId: string;
  customerId: string;
  status: string;
  recurringAmount: { amount: number; currency: string };
  interval: string;
  intervalCount: number;
  cancelAtPeriodEnd: boolean;
  currentPeriodEnd?: string;
  nextBillingAt?: string;
  createdAt: string;
}

interface LaneC {
  orgName: string | null;
  subs: Map<string, FakeSub>;
  usage: Map<string, { customerId: string; event: string }>;
}

// Kept beside the shared state (not in it), so this block's state needs no change to Wave3State.
const laneC = new WeakMap<FakeState, LaneC>();

/** Billing and organisation state of the fake. `cus_FAKE0001` is the demo customer. */
export function laneCState(s: FakeState): LaneC {
  let x = laneC.get(s);
  if (!x) {
    const day = 86_400_000;
    const sub = (n: number, customerId: string, status: string, amount: number, cancelAtPeriodEnd = false): FakeSub => ({
      subscriptionId: `sub_FAKE${String(n).padStart(4, "0")}`,
      customerId,
      status,
      recurringAmount: { amount, currency: "usd" },
      interval: "month",
      intervalCount: 1,
      cancelAtPeriodEnd,
      currentPeriodEnd: new Date(Date.now() + 12 * day).toISOString(),
      nextBillingAt: status === "active" ? new Date(Date.now() + 12 * day).toISOString() : undefined,
      createdAt: new Date(Date.now() - 80 * day).toISOString(),
    });
    x = { orgName: null, subs: new Map(), usage: new Map() };
    for (const v of [sub(1, "cus_FAKE0001", "active", 29), sub(2, "cus_FAKE0002", "active", 99)]) x.subs.set(v.subscriptionId, v);
    laneC.set(s, x);
  }
  return x;
}

/** The customer cancels on the billing portal: the plan ends when the paid period does. */
export function cancelFakeSubscription(s: FakeState, customerId: string): boolean {
  const sub = [...laneCState(s).subs.values()].find((v) => v.customerId === customerId && v.status === "active");
  if (sub) sub.cancelAtPeriodEnd = true;
  return !!sub;
}

const frame = (name: string, data: unknown) => `event: ${name}\ndata: ${JSON.stringify(data)}\n\n`;

/** A scripted model: a plain echo, or a send_email call when asked to email, then a closing line once the tool answers. */
function scripted(messages: Body[], tools: Body[]): { text: string; toolCalls: { id: string; name: string; arguments: Body }[] } {
  const last = messages[messages.length - 1];
  const content = String(last.content ?? "");
  if (last.role === "tool") {
    let out: Body = {};
    try {
      out = JSON.parse(content) as Body;
    } catch {}
    if (out.error) return { text: `That didn't go through: ${String((out.error as Body).message ?? "it was refused")}`, toolCalls: [] };
    return { text: out.status === "sent" ? "Done. The email is on its way." : "Done.", toolCalls: [] };
  }
  if (/\bemail\b/i.test(content) && tools.some((t) => t.name === "send_email")) {
    const to = content.match(/[^\s@]+@[^\s@]+\.[^\s@.,]+/)?.[0] ?? "sam@example.com";
    return { text: "Sure, I'll prepare that email. ", toolCalls: [{ id: `tc_FAKE${String(content.length).padStart(4, "0")}`, name: "send_email", arguments: { to, subject: "Hello", text: "Hi, just checking in." } }] };
  }
  return { text: `You said: ${content}`, toolCalls: [] };
}

handlers["llm.chat"] = (c, b) => {
  const messages = Array.isArray(b.messages) ? (b.messages as Body[]) : [];
  if (messages.length < 1) return c.fail(400, "invalid_request", "messages must hold at least one message.");
  const ids = new Set<string>();
  for (const m of messages) {
    if (m.role === "tool") {
      if (typeof m.toolCallId !== "string" || !ids.has(m.toolCallId)) return c.fail(400, "invalid_request", "A tool message must answer a tool call from the assistant message before it.");
    } else if (m.role === "assistant") for (const t of (m.toolCalls as Body[]) ?? []) ids.add(String(t.id));
    else if (m.role !== "user" && m.role !== "system") return c.fail(400, "invalid_request", "Every message needs a role of system, user, assistant or tool.");
  }
  const { text, toolCalls } = scripted(messages, Array.isArray(b.tools) ? (b.tools as Body[]) : []);
  const usage = { inputTokens: 7 * messages.length, outputTokens: Math.ceil(text.length / 4) };
  const result = { text, toolCalls, finishReason: toolCalls.length ? "tool_calls" : "stop", usage };
  if (!(c.headers.accept ?? "").includes("text/event-stream")) return c.json(200, result);
  const frames = [
    ...(text.match(/\S+\s*/g) ?? []).map((w) => frame("text_delta", { text: w })),
    ...toolCalls.flatMap((t, index) => [frame("tool_call_start", { index, id: t.id, name: t.name }), frame("tool_call_delta", { index, arguments: JSON.stringify(t.arguments) }), frame("tool_call_end", { index })]),
    frame("usage", usage),
    frame("done", { finishReason: result.finishReason, result, price_micro: 2_600 }),
  ];
  const enc = new TextEncoder();
  return new Response(new ReadableStream({ start: (ctl) => (frames.forEach((f) => ctl.enqueue(enc.encode(f))), ctl.close()) }), { status: 200, headers: { "content-type": "text/event-stream" } });
};

const PORTAL_MS = 15 * 60_000;
const sub = (s: FakeSub) => ({ ...s });

handlers["billing.subscriptions.list"] = (c, b) => {
  const rows = [...laneCState(c.s).subs.values()].filter((x) => (!b.customerId || x.customerId === b.customerId) && (!b.status || x.status === b.status));
  return c.json(200, { results: rows.map(sub) });
};

handlers["billing.portal.create"] = (c, b) => {
  if (typeof b.customerId !== "string" || ![...laneCState(c.s).subs.values()].some((x) => x.customerId === b.customerId)) return c.fail(404, "not_found", "Customer not found in your billing account.");
  const back = typeof b.returnUrl === "string" ? b.returnUrl : "http://localhost/";
  return c.json(200, { portalUrl: `${new URL(back).origin}/subscriptions/stand-in?customer=${encodeURIComponent(b.customerId)}&return=${encodeURIComponent(back)}`, expiresAt: new Date(c.now + PORTAL_MS).toISOString() });
};

handlers["billing.usage.record"] = (c, b) => {
  if (typeof b.customerId !== "string" || typeof b.event !== "string" || b.event === "") return c.fail(400, "invalid_request", "Send customerId and event.");
  const key = c.headers["idempotency-key"] ?? `${b.customerId}:${b.event}:${b.timestamp ?? c.now}`;
  const usage = laneCState(c.s).usage;
  const duplicate = usage.has(key);
  usage.set(key, { customerId: b.customerId, event: b.event });
  return c.json(200, { recorded: true, duplicate });
};

/** The approval a held call waits on, as GET /v1/jobs/{id} answers for it. */
function approvalJob(c: FakeCtx, id: string): Response {
  const a = c.s.approvals.get(id);
  if (!a) return c.fail(404, "not_found", "Job not found. Check the job_id.");
  const expired = a.status === "pending" && a.expiresAt <= c.now;
  const base = { job_id: a.id, approval_id: a.id, capability: a.capability, approval: { status: expired ? "expired" : a.status }, created_at: new Date(a.createdAt).toISOString(), updated_at: new Date(a.decidedAt ?? a.createdAt).toISOString() };
  const failed = (message: string) => c.json(200, { ...base, status: "failed", error: { code: "forbidden", message, effect: "none" } });
  if (expired) return failed("No member approved this call in time, so nothing ran.");
  if (a.status === "denied") return failed("A member declined this call, so nothing ran and nothing was charged.");
  if (a.status === "approved") return c.json(200, { ...base, status: "done", result: { status: "sent" } });
  return c.json(200, { ...base, status: a.status === "cancelled" ? "cancelled" : "running" });
}

const ORG = "org_FAKE0001";

/** The non-capability routes of the chat, account and subscriptions blocks. */
function laneCRoutes(c: FakeCtx): Response | undefined {
  const job = c.method === "GET" ? c.path.match(/^\/v1\/jobs\/(apr_[^/]+)$/) : null;
  if (job) return approvalJob(c, decodeURIComponent(job[1]));
  if (c.method === "GET" && c.path === "/v1/members/me") {
    const me = c.s.members.find((x) => x.member_id === c.headers["pramaan-member"]);
    if (!me) return c.fail(403, "forbidden", "This call acts for the workspace, not a member. Use a member's session or member token, or a key made for one member.");
    return c.json(200, { ...me, can_decide: me.may_approve, via: "key" });
  }
  if (c.path === "/v1/organization") {
    const st = laneCState(c.s);
    if (c.method === "GET") return c.json(200, { organization_id: ORG, name: st.orgName, name_set: st.orgName !== null });
    if (c.method === "PUT") {
      const me = c.s.members.find((x) => x.member_id === c.headers["pramaan-member"]);
      if (me && me.role !== "owner" && me.role !== "admin") return c.fail(403, "forbidden", "Only an owner or an admin can set the organisation's name.");
      const name = typeof (c.body as Body | undefined)?.name === "string" ? ((c.body as Body).name as string).trim().replace(/\s+/g, " ") : "";
      if (name.length < 2 || name.length > 200) return c.fail(400, "invalid_request", "The name must be 2 to 200 characters.");
      if (name.includes("@")) return c.fail(400, "invalid_request", "The name can't contain an email address.");
      st.orgName = name;
      return c.json(200, { organization_id: ORG, name, name_set: true });
    }
  }
  return undefined;
}

// ---- voice call (voice.browser-session.*, voice.browser-call.start, voice.call.end) ----
// A browser phone session, its events, and outbound calls. A call waits for a member's yes (the
// API asks for one on an irreversible call made with a key), then dials, then connects one fake
// step later. Events are worked out when they are read, from the fake clock.

const E164 = /^\+[1-9]\d{6,14}$/;
/** Dialling this number ends busy instead of connecting. */
export const FAKE_BUSY_NUMBER = "+15555550199";

interface VoiceEvent {
  id: string;
  type: string;
  at: string;
  callRef?: string;
  direction?: "outbound";
  from?: string;
  to?: string;
  reason?: string;
}
interface VoiceSession {
  ref: string;
  from: string;
  expiresAt: number;
  status: "open" | "closed" | "expired";
  events: VoiceEvent[];
}
interface VoiceCall {
  ref: string;
  session: string;
  to: string;
  approval: string;
  state: "pending" | "dialing" | "connected" | "ended" | "failed";
  placedAt?: number;
}
export interface VoiceState {
  sessions: Map<string, VoiceSession>;
  calls: Map<string, VoiceCall>;
  byKey: Map<string, string>;
}
const voice = (s: FakeState): VoiceState => (wave3(s).voice ??= { sessions: new Map(), calls: new Map(), byKey: new Map() });

function voiceTick(c: FakeCtx, sess: VoiceSession) {
  const v = voice(c.s);
  const emit = (type: string, at: number, call?: VoiceCall, reason?: string) =>
    sess.events.push({
      id: `ve_${sess.events.length + 1}`,
      type,
      at: new Date(at).toISOString(),
      ...(call ? { callRef: call.ref, direction: "outbound" as const, from: sess.from, to: call.to } : {}),
      ...(reason ? { reason } : {}),
    });
  const finish = (call: VoiceCall, at: number, type: "call.ended" | "call.failed", reason: string) => {
    call.state = type === "call.failed" ? "failed" : "ended";
    emit(type, at, call, reason);
  };
  for (const call of [...v.calls.values()].filter((x) => x.session === sess.ref)) {
    if (call.state === "pending") {
      const a = c.s.approvals.get(call.approval);
      if (a?.status === "approved") {
        call.state = "dialing";
        call.placedAt = a.decidedAt ?? c.now;
        emit("call.dialing", call.placedAt, call);
      } else if (a && a.status !== "pending") v.calls.delete(call.ref);
    }
    if (call.state === "dialing" && c.now >= call.placedAt! + c.s.stepMs) {
      const at = call.placedAt! + c.s.stepMs;
      if (call.to === FAKE_BUSY_NUMBER) finish(call, at, "call.failed", "busy");
      else {
        call.state = "connected";
        emit("call.connected", at, call);
      }
    }
  }
  if (sess.status === "open" && sess.expiresAt <= c.now) voiceClose(c, sess, "expired");
}

function voiceClose(c: FakeCtx, sess: VoiceSession, status: "closed" | "expired") {
  const emitEnd = (call: VoiceCall) => {
    call.state = "ended";
    sess.events.push({ id: `ve_${sess.events.length + 1}`, type: "call.ended", at: new Date(c.now).toISOString(), callRef: call.ref, direction: "outbound", from: sess.from, to: call.to, reason: "session_closed" });
  };
  for (const call of voice(c.s).calls.values()) if (call.session === sess.ref && (call.state === "dialing" || call.state === "connected")) emitEnd(call);
  sess.status = status;
  sess.events.push({ id: `ve_${sess.events.length + 1}`, type: status === "closed" ? "session.closed" : "session.expired", at: new Date(c.now).toISOString() });
}

function openSession(c: FakeCtx, ref: unknown): VoiceSession | Response {
  const sess = voice(c.s).sessions.get(String(ref));
  if (!sess) return c.fail(404, "not_found", "Phone session not found. Check the ref.");
  voiceTick(c, sess);
  return sess;
}

handlers["voice.browser-session.create"] = (c, b) => {
  if (typeof b.agent !== "string" || b.agent.trim() === "" || b.agent.length > 128) return c.fail(400, "invalid_request", "agent is required: your own id for the person using the phone.");
  if (typeof b.from !== "string" || !E164.test(b.from)) return c.fail(400, "invalid_request", "from must be one of your numbers in E.164 form, like +14155550100.");
  if (typeof b.origin !== "string" || !/^(https:\/\/[^/]+|http:\/\/localhost(:\d+)?)$/.test(b.origin)) return c.fail(400, "invalid_request", "origin must be the exact origin of your page, like https://desk.example.com.");
  const life = b.lifetimeSeconds === undefined ? 900 : Number(b.lifetimeSeconds);
  if (!Number.isInteger(life) || life < 60 || life > 3600) return c.fail(400, "invalid_request", "lifetimeSeconds must be from 60 to 3600.");
  const v = voice(c.s);
  const key = c.headers["idempotency-key"];
  const seen = key ? v.byKey.get(`session:${key}`) : undefined;
  const ref = seen ?? nextId(c.s, "ref");
  if (!seen) {
    v.sessions.set(ref, { ref, from: b.from, expiresAt: c.now + life * 1000, status: "open", events: [] });
    if (key) v.byKey.set(`session:${key}`, ref);
  }
  const sess = v.sessions.get(ref)!;
  return c.json(200, { ref, connectUrl: `wss://voice.pramaan.fake/s/${ref}`, credential: `cred_${ref}`, expiresAt: new Date(sess.expiresAt).toISOString(), number: sess.from });
};

handlers["voice.browser-call.start"] = (c, b) => {
  const sess = openSession(c, b.ref);
  if (sess instanceof Response) return sess;
  if (sess.status !== "open") return c.fail(409, "conflict", "That phone session has ended. Open a new one.");
  if (typeof b.to !== "string" || !E164.test(b.to)) return c.fail(400, "invalid_request", "to must be a phone number in E.164 form, like +14155550100.");
  const v = voice(c.s);
  const key = c.headers["idempotency-key"];
  const seen = key ? v.byKey.get(`call:${sess.ref}:${key}`) : undefined;
  if (seen) return c.json(202, { job_id: v.calls.get(seen)?.approval, status: "running", held_micro: 0 });
  const callRef = nextId(c.s, "ref");
  const approval = c.addApproval({ capability: "voice.browser-call.start", priceMicro: 30_000, input: { to: b.to }, requestedBy: { kind: "key" }, createdAt: c.now });
  v.calls.set(callRef, { ref: callRef, session: sess.ref, to: b.to, approval, state: "pending" });
  if (key) v.byKey.set(`call:${sess.ref}:${key}`, callRef);
  return c.json(202, { job_id: approval, status: "running", held_micro: 0 });
};

handlers["voice.call.end"] = (c, b) => {
  const call = voice(c.s).calls.get(String(b.ref));
  if (!call || call.state === "pending") return c.fail(404, "not_found", "Call not found. Check the ref.");
  const sess = voice(c.s).sessions.get(call.session)!;
  voiceTick(c, sess);
  if (call.state === "dialing" || call.state === "connected") {
    call.state = "ended";
    sess.events.push({ id: `ve_${sess.events.length + 1}`, type: "call.ended", at: new Date(c.now).toISOString(), callRef: call.ref, direction: "outbound", from: sess.from, to: call.to, reason: "completed" });
  }
  return c.json(200, { callRef: call.ref, state: call.state === "failed" ? "failed" : "ended" });
};

handlers["voice.browser-session.events"] = (c, b) => {
  const sess = openSession(c, b.ref);
  if (sess instanceof Response) return sess;
  const after = typeof b.cursor === "string" ? sess.events.findIndex((e) => e.id === b.cursor) + 1 : 0;
  return c.json(200, { events: sess.events.slice(after, after + (Number(b.limit) || 100)) });
};

handlers["voice.browser-session.close"] = (c, b) => {
  const sess = openSession(c, b.ref);
  if (sess instanceof Response) return sess;
  if (sess.status === "open") voiceClose(c, sess, "closed");
  return c.json(200, { status: sess.status === "expired" ? "expired" : "closed" });
};

// Optional bot-check evidence, through the same fake capability transport as the calendar calls.
handlers["auth.bot-check.verify"] = (c, b) => {
  if (typeof b.token !== "string" || !b.token) return c.fail(400, "invalid_request", "Complete the security check.");
  return c.json(200, { passed: b.token === "test-token" });
};

// ---- booking (calendar.free-busy.get, calendar.event.create) ----
// The person's own calendar, once connected. Every weekday is busy 15:00 to 16:00 UTC. A new event
// is irreversible and sends an invitation, so with a key it waits for a member's yes; once approved
// it is on the calendar and shows as busy. Times are read as UTC.

export interface CalEvent {
  ref: string;
  user: string;
  createdAt?: string;
  allDay?: boolean;
  transparency?: "free" | "transparent" | "busy" | "opaque";
  responseStatus?: "needs_action" | "accepted" | "declined" | "tentative";
  status?: "confirmed" | "tentative" | "cancelled";
  title: string;
  start: number;
  end: number;
}
export interface CalendarState {
  immediate?: boolean;
  events: CalEvent[];
  pending: { approval: string; event: CalEvent }[];
  byKey: Map<string, string>;
}
export const calendar = (s: FakeState): CalendarState => (wave3(s).calendar ??= { events: [], pending: [], byKey: new Map() });

function calendarTick(c: FakeCtx) {
  const cal = calendar(c.s);
  for (const p of [...cal.pending]) {
    const a = c.s.approvals.get(p.approval);
    if (a && a.status === "pending" && a.expiresAt > c.now) continue;
    cal.pending.splice(cal.pending.indexOf(p), 1);
    if (a?.status === "approved") cal.events.push(p.event);
  }
}

const CALENDAR_APPS = ["googlecalendar", "outlook"];

/** The calendar's owner, if their calendar app is connected. */
function calendarOwner(c: FakeCtx, b: Body): { user: string } | Response {
  const user = b.endUserRef;
  if (typeof user !== "string" || !/^[A-Za-z0-9_.-]{1,128}$/.test(user)) return c.fail(400, "invalid_request", "endUserRef is required: your own reference for the end user.");
  if (typeof b.app !== "string" || !CALENDAR_APPS.includes(b.app)) return c.fail(400, "invalid_request", "app must be googlecalendar or outlook.");
  const live = platform(c.s).connections.get(user)?.some((x) => x.app === b.app && x.status === "active");
  return live ? { user } : c.fail(409, "connection_required", "This calendar isn't connected. Connect it, then try again.");
}

const DAY_MS = 86_400_000;

handlers["calendar.free-busy.get"] = (c, b) => {
  calendarTick(c);
  const first = Array.isArray(b.calendars) ? (b.calendars[0] as Body | undefined) : undefined;
  if (!first || (b.calendars as unknown[]).length > 20) return c.fail(400, "invalid_request", "calendars must hold 1 to 20 calendars.");
  const owner = calendarOwner(c, first);
  if (owner instanceof Response) return owner;
  const after = Date.parse(String(b.after));
  const before = Date.parse(String(b.before));
  if (Number.isNaN(after) || Number.isNaN(before) || before <= after) return c.fail(400, "invalid_request", "after and before must be UTC instants, with before later.");
  if (before - after > 62 * DAY_MS) return c.fail(400, "invalid_request", "The window can be at most 62 days.");
  const busy: [number, number][] = [];
  for (let day = Math.floor(after / DAY_MS) * DAY_MS; day < before; day += DAY_MS) {
    const weekday = new Date(day).getUTCDay();
    if (weekday >= 1 && weekday <= 5) busy.push([day + 15 * 3_600_000, day + 16 * 3_600_000]);
  }
  for (const e of calendar(c.s).events) if (e.user === owner.user && e.status !== "cancelled" && e.responseStatus !== "declined" && e.transparency !== "free" && e.transparency !== "transparent") busy.push([e.start, e.end]);
  const merged: [number, number][] = [];
  for (const [start, end] of busy.sort((a, b) => a[0] - b[0])) {
    const last = merged.at(-1);
    if (last && start <= last[1]) last[1] = Math.max(last[1], end);
    else merged.push([start, end]);
  }
  const rows = merged
    .filter(([s, e]) => e > after && s < before)
    .sort((x, y) => x[0] - y[0])
    .map(([s, e]) => ({ start: new Date(Math.max(s, after)).toISOString(), end: new Date(Math.min(e, before)).toISOString() }));
  return c.json(200, { results: [{ calendar: 0, busy: rows }] });
};

handlers["calendar.event.create"] = (c, b) => {
  calendarTick(c);
  const owner = calendarOwner(c, b);
  if (owner instanceof Response) return owner;
  if (typeof b.title !== "string" || b.title.trim() === "" || b.title.length > 1000) return c.fail(400, "invalid_request", "title is required, up to 1,000 characters.");
  const start = Date.parse(`${b.start}Z`);
  const end = Date.parse(`${b.end}Z`);
  if (Number.isNaN(start) || Number.isNaN(end) || end <= start) return c.fail(400, "invalid_request", "start and end are required wall-clock times, like 2026-10-15T14:00:00, with end later.");
  for (const a of (b.attendees as Body[] | undefined) ?? []) if (typeof a.email !== "string" || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a.email)) return c.fail(400, "invalid_request", "Every attendee needs a valid email address.");
  const cal = calendar(c.s);
  const key = c.headers["idempotency-key"];
  const seen = key ? cal.byKey.get(key) : undefined;
  if (seen) return c.json(202, { job_id: seen, status: "running", held_micro: 0 });
  const event = { ref: nextId(c.s, "ref"), createdAt: new Date(c.now).toISOString(), user: owner.user, title: b.title, start, end };
  if (cal.immediate) {
    cal.events.push(event);
    return c.json(200, eventRow(event));
  }
  const approval = c.addApproval({ capability: "calendar.event.create", priceMicro: 3_000, input: b, requestedBy: { kind: "key" }, createdAt: c.now });
  cal.pending.push({ approval, event });
  if (key) cal.byKey.set(key, approval);
  return c.json(202, { job_id: approval, status: "running", held_micro: 0 });
};

function eventRow(e: CalEvent) {
  return { ref: e.ref, createdAt: e.createdAt, title: e.title, kind: "single", allDay: e.allDay ?? false,
    ...(e.transparency ? { transparency: e.transparency } : {}), ...(e.responseStatus ? { responseStatus: e.responseStatus } : {}),
    startAt: new Date(e.start).toISOString(), endAt: new Date(e.end).toISOString(), timezone: "UTC", status: e.status ?? "confirmed" };
}
handlers["calendar.events.list"] = (c, b) => {
  calendarTick(c);
  const owner = calendarOwner(c, b);
  if (owner instanceof Response) return owner;
  const after = Date.parse(String(b.after));
  const before = Date.parse(String(b.before));
  if (!Number.isFinite(after) || !Number.isFinite(before) || after >= before) return c.fail(400, "invalid_request", "Choose a valid time range.");
  const events = calendar(c.s).events.filter((e) => e.user === owner.user && e.start < before && e.end > after).sort((a, b) => a.start - b.start);
  const offset = Number(b.cursor ?? 0);
  const limit = Number(b.limit ?? 10);
  return c.json(200, { results: events.slice(offset, offset + limit).map(eventRow), ...(offset + limit < events.length ? { nextCursor: String(offset + limit) } : {}) });
};
handlers["calendar.event.delete"] = (c, b) => {
  const owner = calendarOwner(c, b);
  if (owner instanceof Response) return owner;
  const cal = calendar(c.s);
  const index = cal.events.findIndex((e) => e.user === owner.user && e.ref === b.ref);
  if (index < 0) return c.fail(404, "not_found", "That booking couldn't be found.");
  cal.events.splice(index, 1);
  return c.json(200, { deleted: true });
};

// ---- e-sign (signature.request.* and signature.requests.list) ----

interface FakeSigner { name: string; email: string; status: "waiting" | "viewed" | "signed"; signedAt?: number }
interface FakeSignature { ref: string; title: string; createdAt: number; signers: FakeSigner[]; reminders: number }
const signatures = new WeakMap<FakeState, Map<string, FakeSignature>>();
const sigs = (s: FakeState) => signatures.get(s) ?? signatures.set(s, new Map()).get(s)!;

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
/** A document id in the shape the API accepts, for the demo's sample agreement. */
export const DEMO_DOCUMENT_ID = "file_FAKE0000000000000000000001";
const FILE_ID = /^file_[0-9A-HJKMNP-TV-Z]{26}$/;

function sigStatus(r: FakeSignature) {
  if (r.signers.every((x) => x.status === "signed")) return "completed";
  if (r.signers.some((x) => x.status === "signed")) return "partially-signed";
  return r.signers.some((x) => x.status === "viewed") ? "viewed" : "sent";
}
const lastSigned = (r: FakeSignature) => Math.max(...r.signers.map((x) => x.signedAt ?? 0));

const held = new WeakSet<FakeState>();
/** The next send waits for a member's yes, as the API holds some calls (a 202 with an approval id). */
export const holdFakeSignatureSend = (s: FakeState) => void held.add(s);

handlers["signature.request.send"] = (c, b) => {
  const text = (v: unknown, max: number) => typeof v === "string" && v.trim() !== "" && v.length <= max;
  if (!text(b.title, 100)) return c.fail(400, "invalid_request", "title is required, up to 100 characters.");
  if (!text(b.subject, 100)) return c.fail(400, "invalid_request", "subject is required, up to 100 characters.");
  const docs = b.documents as Body[] | undefined;
  if (!Array.isArray(docs) || docs.length < 1 || docs.length > 10) return c.fail(400, "invalid_request", "documents must hold 1 to 10 files.");
  for (const d of docs) {
    if (typeof d.fileId !== "string" || !FILE_ID.test(d.fileId)) return c.fail(400, "invalid_request", "fileId must be the id of a file you uploaded.");
    if (typeof d.filename !== "string" || !/^[^/\\]+\.(pdf|png|jpe?g)$/i.test(d.filename)) return c.fail(400, "invalid_request", "filename must end in .pdf, .png or .jpg.");
  }
  const signers = b.signers as Body[] | undefined;
  if (!Array.isArray(signers) || signers.length < 1 || signers.length > 20) return c.fail(400, "invalid_request", "signers must hold 1 to 20 people.");
  for (const x of signers) if (!text(x.name, 100) || typeof x.email !== "string" || !EMAIL.test(x.email)) return c.fail(400, "invalid_request", "Every signer needs a name and an email address.");
  if (new Set(signers.map((x) => String(x.email).toLowerCase())).size !== signers.length) return c.fail(400, "invalid_request", "Each signer needs a different email address.");
  if (held.delete(c.s)) return c.json(202, { approval_id: nextId(c.s, "apr"), status: "pending" });
  const ref = nextId(c.s, "ref");
  sigs(c.s).set(ref, {
    ref, title: b.title as string, createdAt: c.now, reminders: 0,
    signers: signers.map((x) => ({ name: x.name as string, email: String(x.email).toLowerCase(), status: "waiting" as const })),
  });
  return c.json(200, { status: "sent", delivery: "email", ref });
};

handlers["signature.requests.list"] = (c) => {
  const rows = [...sigs(c.s).values()].sort((a, z) => z.createdAt - a.createdAt);
  return c.json(200, { results: rows.map((r) => ({ ref: r.ref, title: r.title, status: sigStatus(r), createdAt: new Date(r.createdAt).toISOString(), updatedAt: new Date(Math.max(r.createdAt, lastSigned(r))).toISOString() })) });
};

handlers["signature.request.get"] = (c, b) => {
  const r = sigs(c.s).get(String(b.ref));
  if (!r) return c.fail(404, "not_found", "Signing request not found. Check the ref.");
  const status = sigStatus(r);
  return c.json(200, {
    title: r.title, status, createdAt: new Date(r.createdAt).toISOString(),
    ...(status === "completed" ? { completedAt: new Date(lastSigned(r)).toISOString() } : {}),
    ...(b.includeSigners === false ? {} : { signers: r.signers.map((x) => ({ name: x.name, email: x.email, status: x.status, ...(x.signedAt ? { signedAt: new Date(x.signedAt).toISOString() } : {}) })) }),
    downloadable: status === "completed",
  });
};

handlers["signature.request.remind"] = (c, b) => {
  const r = sigs(c.s).get(String(b.ref));
  if (!r) return c.fail(404, "not_found", "Signing request not found. Check the ref.");
  if (b.confirm !== true) return c.fail(400, "invalid_request", "confirm must be true to email a reminder.");
  const who = r.signers.find((x) => x.email === String(b.signerEmail).toLowerCase());
  if (!who || who.status === "signed") return c.fail(400, "invalid_request", "That email isn't a current signer on this request.");
  r.reminders++;
  return c.json(200, { status: "requested" });
};

const PDF = "data:application/pdf;base64,JVBERi0xLjQKMSAwIG9iajw8L1R5cGUvQ2F0YWxvZy9QYWdlcyAyIDAgUj4+ZW5kb2JqCjIgMCBvYmo8PC9UeXBlL1BhZ2VzL0tpZHNbMyAwIFJdL0NvdW50IDE+PmVuZG9iagozIDAgb2JqPDwvVHlwZS9QYWdlL1BhcmVudCAyIDAgUi9NZWRpYUJveFswIDAgMjAwIDIwMF0+PmVuZG9iagp0cmFpbGVyPDwvUm9vdCAxIDAgUj4+CiUlRU9G";
handlers["signature.request.download"] = (c, b) => {
  const r = sigs(c.s).get(String(b.ref));
  if (!r) return c.fail(404, "not_found", "Signing request not found. Check the ref.");
  if (sigStatus(r) !== "completed") return c.fail(409, "conflict", "The agreement isn't fully signed yet, so there is nothing to download.");
  return c.json(200, { state: "completed", file: { fileId: `file_FAKE${String(wave3(c.s).seq++).padStart(22, "0")}`, url: PDF, expiresAt: new Date(c.now + 7 * 24 * 3_600_000).toISOString(), contentType: "application/pdf", sizeBytes: 300 } });
};

/** A signer opens the emailed link (what the signing page does). */
export function viewFakeSignature(s: FakeState, ref: string, email: string): boolean {
  const x = sigs(s).get(ref)?.signers.find((y) => y.email === email.toLowerCase());
  if (!x) return false;
  if (x.status === "waiting") x.status = "viewed";
  return true;
}
/** A signer signs on the provider's signing page. */
export function signFakeSignature(s: FakeState, ref: string, email: string): boolean {
  const x = sigs(s).get(ref)?.signers.find((y) => y.email === email.toLowerCase());
  if (!x) return false;
  Object.assign(x, { status: "signed", signedAt: s.now() });
  return true;
}
/** How many reminders went out for a request (for tests). */
export const fakeReminders = (s: FakeState, ref: string) => sigs(s).get(ref)?.reminders ?? 0;

// ---- upload (POST /v1/files/uploads, /v1/files/{id}/finish, GET and DELETE /v1/files) ----

interface FakeFile { fileId: string; kind: string; contentType: string; sizeBytes: number; createdAt: number; bytes?: Uint8Array; ready: boolean }
const files = new WeakMap<FakeState, Map<string, FakeFile>>();
const fileMap = (s: FakeState) => files.get(s) ?? files.set(s, new Map()).get(s)!;
const KINDS = ["audio", "image", "video", "document", "data"];
/** The API's direct-upload limits: audio, document and data 100 MB, video 500 MB, image 20 MB. */
const LIMIT: Record<string, number> = { audio: 100e6, document: 100e6, data: 100e6, video: 500e6, image: 20e6 };
const FILE_DAYS = 7;
const fileFacts = (c: FakeCtx, f: FakeFile) => ({
  fileId: f.fileId, kind: f.kind, origin: "upload", contentType: f.contentType, sizeBytes: f.sizeBytes,
  createdAt: new Date(f.createdAt).toISOString(), expiresAt: new Date(f.createdAt + FILE_DAYS * 86_400_000).toISOString(),
  url: `/api/demo/storage/${f.fileId}`,
});

/** The bytes arrive at the storage link (what the browser's PUT does). */
export function storeFakeUpload(s: FakeState, fileId: string, bytes: Uint8Array): boolean {
  const f = fileMap(s).get(fileId);
  if (!f) return false;
  f.bytes = bytes;
  return true;
}
/** What the storage link serves for a ready file. */
export const fakeUploadBytes = (s: FakeState, fileId: string) => { const f = fileMap(s).get(fileId); return f?.ready && f.bytes ? { bytes: f.bytes, contentType: f.contentType } : undefined; };

function fileRoutes(c: FakeCtx): Response | undefined {
  const body = (c.body ?? {}) as Body;
  if (c.method === "POST" && c.path === "/v1/files/uploads") {
    const { kind, contentType, sizeBytes } = body;
    if (typeof kind !== "string" || !KINDS.includes(kind) || typeof contentType !== "string" || !contentType || !Number.isInteger(sizeBytes) || (sizeBytes as number) < 1)
      return c.fail(400, "invalid_request", "Send kind, contentType and a positive integer sizeBytes.");
    if ((sizeBytes as number) > LIMIT[kind]) return c.fail(400, "invalid_request", `A ${kind} file can be at most ${LIMIT[kind] / 1e6} MB.`);
    const fileId = `file_FAKE${String(1000 + ++wave3(c.s).seq).padStart(22, "0")}`;
    fileMap(c.s).set(fileId, { fileId, kind, contentType, sizeBytes: sizeBytes as number, createdAt: c.now, ready: false });
    return c.json(201, { fileId, uploadUrl: `/api/demo/storage/${fileId}`, headers: { "content-type": contentType }, expiresAt: new Date(c.now + 15 * 60_000).toISOString() });
  }
  let m = c.path.match(/^\/v1\/files\/([^/]+)\/finish$/);
  if (c.method === "POST" && m) {
    const f = fileMap(c.s).get(m[1]);
    if (!f) return c.fail(404, "not_found", "File not found.");
    if (f.bytes?.length !== f.sizeBytes) return c.fail(400, "invalid_request", "The file didn't arrive in full. Start a new upload.");
    f.ready = true;
    return c.json(200, fileFacts(c, f));
  }
  if (c.method === "GET" && c.path === "/v1/files") {
    const rows = [...fileMap(c.s).values()].filter((f) => f.ready).sort((a, z) => z.createdAt - a.createdAt);
    return c.json(200, { results: rows.map((f) => fileFacts(c, f)) });
  }
  m = c.path.match(/^\/v1\/files\/([^/]+)$/);
  if (m && (c.method === "GET" || c.method === "DELETE")) {
    const f = fileMap(c.s).get(m[1]);
    if (!f) return c.fail(404, "not_found", "File not found.");
    if (c.method === "GET") return c.json(200, fileFacts(c, f));
    fileMap(c.s).delete(m[1]);
    return c.json(200, { deleted: true });
  }
  return undefined;
}

/** The wave 3 routes of this fake. Returns undefined for a route it doesn't serve. */
export function wave3Routes(c: FakeCtx): Response | undefined {
  const file = fileRoutes(c);
  if (file) return file;
  const m = c.path.match(/^\/v1\/capabilities\/([^/]+)$/);
  const h = c.method === "POST" && m ? handlers[decodeURIComponent(m[1])] : undefined;
  return h ? h(c, (c.body ?? {}) as Body) : laneCRoutes(c);
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { plainProblem } from "./plain";

// Browser half of the shared Pramaan helpers: calls this app's own /api/pramaan routes, never
// Pramaan itself, so no key is needed here.

/** An error from this app's API, with the server's own message and next step. */
export class ApiError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly next?: string,
    readonly status?: number,
    /** Present on a low-balance refusal: where to add credit. */
    readonly topUp?: { message: string; links: { label: string; url: string }[]; balance_micro: number },
  ) {
    super(message);
  }
}

export async function api<T>(url: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(url, { cache: "no-store", ...init });
  } catch {
    throw new ApiError("Can't reach the server. Check your connection and try again.", "network");
  }
  const data = await res.json().catch(() => undefined);
  if (!res.ok) {
    const e = data?.error ?? {};
    const p = plainProblem(e.code ?? "internal", res.status, e.message ?? "", e.next);
    throw new ApiError(p.message, e.code ?? "internal", p.next, res.status, e.top_up);
  }
  return data as T;
}

/** Micro-USD as dollars to 2 decimals: 905219 -> "$0.91". */
export function formatMicro(micro: number): string {
  if (micro > 0 && micro < 5_000) return "under $0.01";
  return `$${(micro / 1_000_000).toFixed(2)}`;
}

/** A most-it-can-cost price as a phrase: "up to $0.12", "$0.01" for a tiny price, "free" for none. Never "up to under". */
export const upTo = (micro: number) => (micro === 0 ? "free" : micro < 5_000 ? formatMicro(micro) : `up to ${formatMicro(micro)}`);

/** The same for a sentence about cost: "at most $0.12", "less than $0.01", "nothing". */
export const atMost = (micro: number) => (micro === 0 ? "nothing" : micro < 5_000 ? "less than $0.01" : `at most ${formatMicro(micro)}`);

/** Tell every block on the page that Pramaan data changed (they reload). */
export const PRAMAAN_CHANGED = "pramaan:changed";
export const announceChange = () => window.dispatchEvent(new Event(PRAMAAN_CHANGED));

/** GETs a URL, optionally every `pollMs`, and again on `announceChange()`. */
export function useResource<T>(url: string | null, pollMs?: number) {
  const [state, setState] = useState<{ data?: T; error?: ApiError; loading: boolean }>({ loading: url !== null });
  const [tick, setTick] = useState(0);
  const reload = useCallback(() => setTick((t) => t + 1), []);

  useEffect(() => {
    if (!url) return;
    let live = true;
    const load = () =>
      api<T>(url).then(
        (data) => live && setState({ data, loading: false }),
        (error: ApiError) => live && setState((s) => ({ data: s.data, error, loading: false })),
      );
    void load();
    const timer = pollMs ? setInterval(load, pollMs) : undefined;
    window.addEventListener(PRAMAAN_CHANGED, load);
    return () => {
      live = false;
      clearInterval(timer);
      window.removeEventListener(PRAMAAN_CHANGED, load);
    };
  }, [url, pollMs, tick]);

  return { ...state, reload };
}

/**
 * The current time, refreshed every `everyMs`, so expiry shows without a reload. It is 0 until
 * the page mounts: reading the clock while rendering breaks prerendering.
 */
export function useNow(everyMs = 1_000): number {
  const [now, setNow] = useState(0);
  useEffect(() => {
    const tick = () => setNow(Date.now());
    tick();
    const timer = setInterval(tick, everyMs);
    return () => clearInterval(timer);
  }, [everyMs]);
  return now;
}

// Plain wording for every screen: names, labels, dates. No ids, no snake_case, no raw JSON reach a
// person through these helpers. Pure functions, safe in the browser and on the server.

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** "31 Oct, 8:03 PM" (and the year when it isn't this year). `time: false` gives "31 Oct". */
export function formatDate(value: string | number | Date | undefined, opts: { time?: boolean } = {}): string {
  if (value === undefined || value === "") return "";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return "";
  const year = d.getFullYear() === new Date().getFullYear() ? "" : ` ${d.getFullYear()}`;
  const day = `${d.getDate()} ${MONTHS[d.getMonth()]}${year}`;
  if (opts.time === false) return day;
  const h = d.getHours() % 12 || 12;
  return `${day}, ${h}:${String(d.getMinutes()).padStart(2, "0")} ${d.getHours() < 12 ? "AM" : "PM"}`;
}

/** A calendar day ("2026-10-30") as "30 Oct". */
export function formatDay(day: string, withYear = true): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(day);
  if (!m) return day;
  const year = !withYear || Number(m[1]) === new Date().getFullYear() ? "" : ` ${m[1]}`;
  return `${Number(m[3])} ${MONTHS[Number(m[2]) - 1]}${year}`;
}

/** Cents as money: 2000 and "usd" is "$20.00". */
export const formatCents = (cents: number, currency = "usd") => new Intl.NumberFormat("en", { style: "currency", currency }).format(cents / 100);

const cap = (s: string) => s.replace(/^./, (c) => c.toUpperCase());

/** "snake_case", "camelCase" and "kebab-case" as plain words: "Account name". */
export const humanize = (key: string) => cap(key.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/[_-]+/g, " ").trim().toLowerCase());

