"use client";

import { useEffect, useState, type FormEvent } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export type PasswordPanelProps = { getBotCheckToken?: () => Promise<string> };
export function PasswordPanel({ getBotCheckToken }: PasswordPanelProps) {
  const [token, setToken] = useState("");
  useEffect(() => {
    const readLink = () => {
      const value = new URLSearchParams(window.location.hash.slice(1)).get("token");
      if (value) {
        setToken(value);
        // The proof stays out of server request logs, referrers and the browser's current address.
        window.history.replaceState(null, "", window.location.pathname);
      }
    };
    readLink();
    window.addEventListener("hashchange", readLink);
    return () => window.removeEventListener("hashchange", readLink);
  }, []);
  return <div className="max-w-xl space-y-6">
    {token ? <PasswordForm key={token} action="reset" token={token} getBotCheckToken={getBotCheckToken} /> : <PasswordForm action="request" getBotCheckToken={getBotCheckToken} />}
    <PasswordForm action="change" />
  </div>;
}

function PasswordForm({ action, token, getBotCheckToken }: { action: "request" | "reset" | "change"; token?: string } & PasswordPanelProps) {
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [failed, setFailed] = useState(false);
  const [done, setDone] = useState(false);
  const title = action === "request" ? "Forgot your password?" : action === "reset" ? "Choose a new password" : "Change your password";
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const values = Object.fromEntries(new FormData(form));
    if (action !== "request" && values.password !== values.confirmPassword) {
      setFailed(true); setMessage("The new passwords do not match."); return;
    }
    setBusy(true); setMessage("");
    try {
      const botCheckToken = action === "change" ? undefined : await getBotCheckToken?.();
      const response = await fetch("/api/pramaan/password-reset", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...values, action, token, botCheckToken }) });
      const body = await response.json();
      setFailed(!response.ok);
      setMessage(typeof body.message === "string" ? body.message : "Please try again later.");
      if (response.ok) { form.reset(); if (action !== "request") setDone(true); }
    } catch { setFailed(true); setMessage("Could not connect. Please try again."); }
    finally { setBusy(false); }
  }
  return <section aria-label={title} className="pr-card space-y-3">
    <h2>{title}</h2>
    <p className="text-sm text-muted-foreground">{action === "request" ? "Enter your email and we will send a link to choose a new password." : action === "reset" ? "Use at least 12 characters. Your link works once for 30 minutes." : "Sign in first, then enter your current password. You will sign in again after changing it."}</p>
    <form onSubmit={submit} className="space-y-3">
      {action === "request" ? <div className="space-y-1"><Label htmlFor={`${action}-email`}>Email</Label><Input id={`${action}-email`} name="email" type="email" autoComplete="email" maxLength={254} required /></div> : <>
        {action === "change" && <div className="space-y-1"><Label htmlFor="current-password">Current password</Label><Input id="current-password" name="currentPassword" type="password" autoComplete="current-password" maxLength={1024} required /></div>}
        <div className="space-y-1"><Label htmlFor={`${action}-password`}>New password</Label><Input id={`${action}-password`} name="password" type="password" autoComplete="new-password" minLength={12} maxLength={1024} required /></div>
        <div className="space-y-1"><Label htmlFor={`${action}-confirm`}>Confirm new password</Label><Input id={`${action}-confirm`} name="confirmPassword" type="password" autoComplete="new-password" minLength={12} maxLength={1024} required /></div>
      </>}
      <Button type="submit" disabled={busy || done}>{busy ? "Please wait…" : action === "request" ? "Send reset link" : "Save password"}</Button>
      {message && <p role={failed ? "alert" : "status"} className="text-sm">{message}</p>}
    </form>
    {done && action === "reset" && <a className="pr-link text-sm" href="/password-reset">Request another link</a>}
  </section>;
}

import "server-only";
import { createPasswordReset, hashResetPassword, proofHash, type ResetOptions } from "./password-reset";
import type { ResetMail } from "./password-reset-sender";
import { memoryResetStore } from "./password-reset-store";

const runtime = globalThis as typeof globalThis & {
  __passwordResetOptions?: ResetOptions;
  __passwordResetFake?: ReturnType<typeof makeFake>;
};
function makeFake() {
  const state = memoryResetStore();
  const mail: ResetMail[] = [];
  const ready = hashResetPassword("Starting password 42").then((passwordHash) => {
    state.users.set("sample-person", { id: "sample-person", email: "sam@example.com", passwordHash });
  });
  return { ...state, mail, ready };
}

export function passwordResetDemoAllowed(request?: Request) {
  if (process.env.PRAMAAN_FAKE !== "1") return false;
  if (process.env.NODE_ENV !== "production") return true;
  if (process.env.PRAMAAN_PASSWORD_RESET_TEST_MODE !== "1") return false;
  try {
    const origin = new URL(process.env.PRAMAAN_PASSWORD_RESET_ORIGIN ?? "");
    return ["localhost", "127.0.0.1"].includes(origin.hostname) && (!request || new URL(request.url).origin === origin.origin);
  } catch { return false; }
}
export async function passwordResetFake() {
  if (!passwordResetDemoAllowed()) throw new Error("Sample accounts are unavailable.");
  const state = runtime.__passwordResetFake ??= makeFake();
  await state.ready;
  return state;
}
export function resetPasswordResetFake() { delete runtime.__passwordResetFake; }

/** Call once from the app's server configuration, with its database and verified session lookup. */
export function configurePasswordReset(options: ResetOptions) { runtime.__passwordResetOptions = options; }

export async function handlePasswordReset(request: Request) {
  if (process.env.PRAMAAN_FAKE === "1") {
    if (!passwordResetDemoAllowed(request)) return unavailable();
    const state = await passwordResetFake();
    const origin = process.env.PRAMAAN_PASSWORD_RESET_ORIGIN ?? "http://localhost:3100";
    return createPasswordReset({
      store: state.store, sender: { send: async (message) => { state.mail.push(message); return "accepted"; } }, origin,
      currentUser: async (req) => {
        const token = req.headers.get("cookie")?.split(";").map((c) => c.trim()).find((c) => c.startsWith("reset_session="))?.slice("reset_session=".length);
        return token ? state.sessions.get(proofHash(token)) : undefined;
      },
    }).handle(request);
  }
  if (runtime.__passwordResetOptions) return createPasswordReset(runtime.__passwordResetOptions).handle(request);
  return unavailable();
}

const unavailable = () => Response.json({ message: "Passwords are unavailable right now. Please try again later." }, { status: 503, headers: { "cache-control": "no-store" } });

import "server-only";
import { readFile } from "node:fs/promises";
import { request } from "node:http";
import path from "node:path";

export type ResetMail = { to: string; subject: string; text: string };
export type SendOutcome = "accepted" | "not-sent" | "unknown";
export interface ResetSender { send(mail: ResetMail, key: string): Promise<SendOutcome> }

/** Refuse before disclosure: capability inputs can appear in an approver's inbox. */
export function capabilityResetSender(_from: string): ResetSender {
  return {
    async send() { return "not-sent"; },
  };
}

/** Kit transport: the local app email module owns the sender and its delivery limits. */
export function moduleResetSender(directory = "/pramaan-modules"): ResetSender {
  return {
    async send(mail, key) {
      let token: string;
      try { token = (await readFile(path.join(directory, "token"), "utf8")).trim(); }
      catch { return "not-sent"; }
      return new Promise<SendOutcome>((resolve) => {
        const body = JSON.stringify(mail);
        const req = request({
          socketPath: path.join(directory, "modules.sock"), path: "/v1/email", method: "POST",
          headers: { authorization: `Bearer ${token}`, "content-type": "application/json", "content-length": Buffer.byteLength(body), "idempotency-key": key },
        }, (res) => {
          // Never return upstream text, addresses or credentials to a public caller.
          res.resume();
          res.on("error", () => resolve("unknown"));
          res.on("end", () => resolve(res.statusCode === 200 || res.statusCode === 202 ? "accepted" : res.statusCode === 504 ? "unknown" : "not-sent"));
        });
        const deadline = setTimeout(() => req.destroy(new Error("Email did not answer.")), 70_000);
        req.on("close", () => clearTimeout(deadline));
        req.on("error", () => resolve("unknown"));
        req.end(body);
      });
    },
  };
}

export function configuredResetSender(): ResetSender {
  const transport = process.env.PRAMAAN_PASSWORD_EMAIL_TRANSPORT ?? "module";
  if (transport === "module") return moduleResetSender();
  if (transport !== "capability") throw new Error("Choose capability or module for password email.");
  return capabilityResetSender(process.env.PRAMAAN_PASSWORD_EMAIL_FROM ?? (process.env.PRAMAAN_FAKE === "1" ? "account@example.com" : ""));
}

import "server-only";
import type { ResetAccount, ResetProof, ResetStore } from "./password-reset";

type Row = { id: string; email: string; password_hash: string };
type QueryResult = { rows: Record<string, unknown>[] };
export interface ResetConnection {
  query(sql: string, values?: unknown[]): Promise<QueryResult>;
  release(): void;
}
export interface ResetPool {
  query(sql: string, values?: unknown[]): Promise<QueryResult>;
  connect(): Promise<ResetConnection>;
}
const account = (row?: Record<string, unknown>): ResetAccount | undefined => {
  const value = row as Row | undefined;
  return value?.email && value.password_hash ? { id: value.id, email: value.email, passwordHash: value.password_hash } : undefined;
};

/** Compatible with the kit's app_users and app_sessions tables and a pg Pool. */
export function postgresResetStore(pool: ResetPool): ResetStore {
  async function transaction<T>(work: (db: ResetConnection) => Promise<T>) {
    const db = await pool.connect();
    try {
      await db.query("BEGIN");
      const value = await work(db);
      await db.query("COMMIT");
      return value;
    } catch (error) { await db.query("ROLLBACK"); throw error; }
    finally { db.release(); }
  }
  async function replace(db: ResetConnection, id: string, hash: string) {
    await db.query("UPDATE app_users SET password_hash=$2 WHERE id=$1", [id, hash]);
    await db.query("DELETE FROM app_password_resets WHERE user_id=$1", [id]);
    await db.query("DELETE FROM app_sessions WHERE user_id=$1", [id]);
  }
  return {
    async find(email) { return account((await pool.query("SELECT id,email,password_hash FROM app_users WHERE lower(email)=$1", [email.toLowerCase()])).rows[0]); },
    async findById(id) { return account((await pool.query("SELECT id,email,password_hash FROM app_users WHERE id=$1", [id])).rows[0]); },
    async revoke(hash) { await pool.query("DELETE FROM app_password_resets WHERE token_hash=$1", [hash]); },
    async issue(proof) {
      await transaction(async (db) => {
        const user = account((await db.query("SELECT id,email,password_hash FROM app_users WHERE id=$1 FOR UPDATE", [proof.userId])).rows[0]);
        if (!user || user.passwordHash !== proof.passwordHash) return;
        await db.query("DELETE FROM app_password_resets WHERE user_id=$1", [proof.userId]);
        await db.query("INSERT INTO app_password_resets(token_hash,user_id,password_hash,expires_at) VALUES($1,$2,$3,to_timestamp($4 / 1000.0))", [proof.hash, proof.userId, proof.passwordHash, proof.expiresAt]);
      });
    },
    async redeem(hash, passwordHash, now) {
      return transaction(async (db) => {
        // Always lock the user first, just as issue/change do, avoiding opposite lock orders.
        const proof = (await db.query("SELECT user_id FROM app_password_resets WHERE token_hash=$1", [hash])).rows[0];
        if (!proof) return false;
        const user = account((await db.query("SELECT id,email,password_hash FROM app_users WHERE id=$1 FOR UPDATE", [proof.user_id])).rows[0]);
        if (!user) return false;
        const valid = (await db.query("SELECT token_hash FROM app_password_resets WHERE token_hash=$1 AND user_id=$2 AND password_hash=$3 AND expires_at>to_timestamp($4 / 1000.0)", [hash, user.id, user.passwordHash, now])).rows[0];
        if (!valid) return false;
        await replace(db, user.id, passwordHash);
        return true;
      });
    },
    async change(id, oldHash, passwordHash) {
      return transaction(async (db) => {
        const user = account((await db.query("SELECT id,email,password_hash FROM app_users WHERE id=$1 FOR UPDATE", [id])).rows[0]);
        if (!user || user.passwordHash !== oldHash) return false;
        await replace(db, id, passwordHash);
        return true;
      });
    },
  };
}

/** Fake storage only. No plaintext reset proofs are kept here. */
export function memoryResetStore() {
  const users = new Map<string, ResetAccount>();
  const proofs = new Map<string, ResetProof>();
  const sessions = new Map<string, string>();
  function replace(id: string, hash: string) {
    const user = users.get(id)!;
    user.passwordHash = hash;
    for (const [key, proof] of proofs) if (proof.userId === id) proofs.delete(key);
    for (const [key, userId] of sessions) if (userId === id) sessions.delete(key);
  }
  const store: ResetStore = {
    async find(email) { const user = [...users.values()].find((u) => u.email.toLowerCase() === email.toLowerCase()); return user && { ...user }; },
    async findById(id) { const user = users.get(id); return user && { ...user }; },
    async revoke(hash) { proofs.delete(hash); },
    async issue(proof) {
      if (users.get(proof.userId)?.passwordHash !== proof.passwordHash) return;
      for (const [key, row] of proofs) if (row.userId === proof.userId) proofs.delete(key);
      proofs.set(proof.hash, { ...proof });
    },
    async redeem(hash, passwordHash, now) {
      const proof = proofs.get(hash);
      if (!proof || proof.expiresAt <= now || users.get(proof.userId)?.passwordHash !== proof.passwordHash) return false;
      replace(proof.userId, passwordHash);
      return true;
    },
    async change(id, oldHash, passwordHash) {
      if (users.get(id)?.passwordHash !== oldHash) return false;
      replace(id, passwordHash);
      return true;
    },
  };
  return { store, users, proofs, sessions };
}

import "server-only";
import { createHash, randomBytes, scrypt, timingSafeEqual } from "node:crypto";
import { after } from "next/server";
import { clientIp, emailLimitKey, limitPublic, verifyPublicBot } from "@/lib/pramaan/public-guard";
import type { ResetSender } from "./password-reset-sender";

export type ResetAccount = { id: string; email: string; passwordHash: string };
export type ResetProof = { hash: string; userId: string; passwordHash: string; expiresAt: number };
export interface ResetStore {
  find(email: string): Promise<ResetAccount | undefined>;
  findById(id: string): Promise<ResetAccount | undefined>;
  issue(proof: ResetProof): Promise<void>;
  revoke(hash: string): Promise<void>;
  /** Atomically consume an unexpired proof, replace the password, delete all proofs and sessions. */
  redeem(hash: string, passwordHash: string, now: number): Promise<boolean>;
  /** Compare the old hash under a lock; replace it and delete all proofs and sessions together. */
  change(id: string, oldHash: string, passwordHash: string): Promise<boolean>;
}
export class PasswordResetError extends Error {
  constructor(public status: number, message: string) { super(message); }
}
export const RESET_ANSWER = "If that email has an account, a password reset link will arrive shortly.";
export const RESET_LIFETIME_MS = 30 * 60_000;
export const proofHash = (proof: string) => createHash("sha256").update(proof).digest("hex");

let passwordWork = 0;
const SCRYPT = { N: 131072, r: 8, p: 1 };
async function derive(password: string, salt: string, parameters = SCRYPT): Promise<Buffer> {
  if (passwordWork >= 4) throw new PasswordResetError(429, "Please wait a moment and try again.");
  passwordWork++;
  try {
    return await new Promise<Buffer>((resolve, reject) => scrypt(password, salt, 64, { ...parameters, maxmem: 256 * 1024 * 1024 }, (error, key) => error ? reject(error) : resolve(key)));
  } finally { passwordWork--; }
}
export async function hashResetPassword(password: string) {
  const salt = randomBytes(16).toString("hex");
  return `scrypt$N=${SCRYPT.N},r=${SCRYPT.r},p=${SCRYPT.p}$${salt}$${(await derive(password, salt)).toString("hex")}`;
}
export async function verifyResetPassword(password: string, encoded: string) {
  const legacy = /^scrypt:([a-f0-9]{32}):([a-f0-9]{128})$/.exec(encoded);
  const modern = /^scrypt\$N=(\d{1,6}),r=(\d{1,2}),p=(\d{1,2})\$([a-f0-9]{32})\$([a-f0-9]{128})$/.exec(encoded);
  const salt = legacy?.[1] ?? modern?.[4]; const key = legacy?.[2] ?? modern?.[5];
  if (!salt || !key) return false;
  const parameters = legacy ? { N: 16384, r: 8, p: 1 } : { N: Number(modern![1]), r: Number(modern![2]), p: Number(modern![3]) };
  // Read older costs, but never let a corrupt row select unbounded work or memory.
  if (![16384, 32768, 65536, 131072].includes(parameters.N) || parameters.r !== 8 || parameters.p < 1 || parameters.N * parameters.p > 131072) return false;
  return timingSafeEqual(await derive(password, salt, parameters), Buffer.from(key, "hex"));
}

/** Hosts can upgrade a successfully verified password on the next sign-in. Changes always upgrade. */
export const resetPasswordNeedsUpgrade = (encoded: string) => !encoded.startsWith("scrypt$N=131072,r=8,p=1$");

/** Sign-in integration: verify first, then replace an older hash with a compare-and-set. */
export async function verifyAndUpgradeResetPassword(store: ResetStore, account: ResetAccount, password: string) {
  if (!await verifyResetPassword(password, account.passwordHash)) return false;
  return !resetPasswordNeedsUpgrade(account.passwordHash) || store.change(account.id, account.passwordHash, await hashResetPassword(password));
}
function newPassword(value: unknown): string {
  if (typeof value !== "string" || value.length < 12 || value.length > 1024)
    throw new PasswordResetError(400, "Use a password between 12 and 1,024 characters.");
  return value;
}

export type ResetOptions = {
  store: ResetStore;
  sender: ResetSender;
  /** Fixed public origin, never taken from a request header. HTTPS except local development. */
  origin: string;
  currentUser(request: Request): Promise<string | undefined>;
  now?: () => number;
};

export function createPasswordReset(options: ResetOptions) {
  const { store, sender } = options;
  const url = new URL(options.origin);
  if (url.origin !== options.origin || (url.protocol !== "https:" && !(url.protocol === "http:" && ["localhost", "127.0.0.1"].includes(url.hostname))))
    throw new Error("A fixed public origin is required for password reset.");
  const now = options.now ?? Date.now;
  async function perform(request: Request, action: unknown, body: Record<string, unknown>) {
    const ip = clientIp(request);
    limitPublic("password-reset-ip", ip, 10, 15 * 60_000, now());
    if (action === "request" || action === "reset") {
      try { await verifyPublicBot(request, body.botCheckToken); }
      catch { throw new PasswordResetError(400, "Please complete the security check and try again."); }
    }
    if (action === "request") {
      const email = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
      if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
        throw new PasswordResetError(400, "Enter a valid email address.");
      limitPublic("password-reset-email", emailLimitKey(email), 3, 15 * 60_000, now());
      // Both addresses take the same response path: no account lookup or delivery before answering.
      after(async () => {
        let key: string | undefined;
        try {
          const account = await store.find(email);
          if (!account) return;
          const token = randomBytes(32).toString("base64url");
          key = proofHash(token);
          await store.issue({ hash: key, userId: account.id, passwordHash: account.passwordHash, expiresAt: now() + RESET_LIFETIME_MS });
          const link = `${options.origin}/password-reset#token=${token}`;
          const outcome = await sender.send({ to: account.email, subject: "Reset your password", text: `Choose a new password using this link:\n${link}\n\nThis link expires in 30 minutes and can be used once. If you did not ask for it, you can ignore this email.` }, `password-reset-${key}`);
          if (outcome !== "accepted") {
            await store.revoke(key);
            console.warn("Password reset delivery.", { outcome, count: 1 });
          }
        } catch {
          if (key) { try { await store.revoke(key); } catch { /* No private error leaves this task. */ } }
          console.warn("Password reset delivery.", { outcome: "failed", count: 1 });
        }
      });
      return { message: RESET_ANSWER };
    }
    if (action === "reset") {
      const password = newPassword(body.password);
      if (typeof body.token !== "string" || !/^[A-Za-z0-9_-]{43}$/.test(body.token))
        throw new PasswordResetError(400, "This link has expired or was already used. Request a new one.");
      if (!await store.redeem(proofHash(body.token), await hashResetPassword(password), now()))
        throw new PasswordResetError(400, "This link has expired or was already used. Request a new one.");
      return { message: "Your password has been changed. Sign in with your new password." };
    }
    if (action === "change") {
      const id = await options.currentUser(request);
      if (!id) throw new PasswordResetError(401, "Sign in to change your password.");
      limitPublic("password-change-account", id, 5, 15 * 60_000, now());
      const account = await store.findById(id);
      const current = typeof body.currentPassword === "string" && body.currentPassword.length <= 1024 ? body.currentPassword : "";
      if (!account || !await verifyResetPassword(current, account.passwordHash))
        throw new PasswordResetError(400, "Your current password is incorrect.");
      if (!await store.change(id, account.passwordHash, await hashResetPassword(newPassword(body.password))))
        throw new PasswordResetError(409, "Your account changed. Sign in again and retry.");
      return { message: "Your password has been changed. Sign in with your new password." };
    }
    throw new PasswordResetError(400, "Choose a password action.");
  }
  return {
    async handle(request: Request): Promise<Response> {
      const headers = { "cache-control": "no-store", "referrer-policy": "no-referrer" };
      try {
        if (request.method !== "POST") throw new PasswordResetError(405, "This action is not available.");
        if (request.headers.get("origin") !== options.origin) throw new PasswordResetError(403, "Refresh this page and try again.");
        if (!request.headers.get("content-type")?.startsWith("application/json")) throw new PasswordResetError(400, "Something in the form was not accepted. Refresh the page and try again.");
        const reader = request.body?.getReader();
        if (!reader) throw new PasswordResetError(400, "Something in the form was not accepted. Refresh the page and try again.");
        const chunks: Uint8Array[] = [];
        let size = 0;
        try {
          for (;;) {
            const part = await reader.read();
            if (part.done) break;
            size += part.value.length;
            if (size > 4096) { await reader.cancel(); throw new PasswordResetError(413, "This request is too large."); }
            chunks.push(part.value);
          }
        } finally { reader.releaseLock(); }
        let body: Record<string, unknown>;
        try {
          body = JSON.parse(Buffer.concat(chunks).toString("utf8"));
          if (!body || typeof body !== "object" || Array.isArray(body)) throw new Error();
        } catch { throw new PasswordResetError(400, "Something in the form was not accepted. Refresh the page and try again."); }
        return Response.json(await perform(request, body.action, body), { headers });
      } catch (error) {
        const status = error instanceof PasswordResetError ? error.status : (error as { status?: number })?.status === 429 ? 429 : 503;
        const message = error instanceof PasswordResetError ? error.message : status === 429 ? "Too many requests. Please try again later." : "Passwords are unavailable right now. Please try again later.";
        return Response.json({ message }, { status, headers });
      }
    },
  };
}

-- Apply after the local account tables. No plaintext reset proof is stored.
CREATE TABLE IF NOT EXISTS app_password_resets (
  token_hash text PRIMARY KEY CHECK (token_hash ~ '^[a-f0-9]{64}$'),
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  password_hash text NOT NULL,
  expires_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS app_password_resets_user ON app_password_resets(user_id);
CREATE INDEX IF NOT EXISTS app_password_resets_expiry ON app_password_resets(expires_at);
